/* AI4DM examples+methods (public) — GENERATED by build.py, do not edit by hand */
window.MX2={"taskGroups":[{"id":"g2d3d","label":"Drawing → Space","hint":"flat drawings gain depth, light and habitation"},{"id":"g3d2d","label":"Image → Drawing","hint":"extract plans, elevations, diagrams and drawing sets from photos and renders"},{"id":"grender","label":"Same design, another representation","hint":"the design stays fixed — the medium, materials, conditions or camera change"},{"id":"gboards","label":"Boards & narratives","hint":"compose drawings into boards, timelines and sequences"}],"stages":[{"id":"ideation","label":"01 · Ideation"},{"id":"iteration","label":"02 · Iteration"},{"id":"final","label":"03 · Final processes"},{"id":"problem","label":"04 · Problem solving"}],"tasks":[{"id":"image-to-plan","title":"Image → Plan","group":"g3d2d","what":"Extract a plan from an image: aerial photos and perspective renders become site plans and CAD-style plan drawings.","cover":"aerial-to-linework-siteplan","order":1},{"id":"image-to-3d-model","title":"Photo → 3D model view","group":"grender","what":"Isolate a building from its photo or render and re-present it as a clean standalone 3D model view.","cover":"photo-to-3d-model-brick-corner","order":1},{"id":"plan-to-perspective","title":"Plan → Perspective","group":"g2d3d","what":"Stand inside the drawing: a floor plan or landscape plan becomes an eye-level or aerial view, testing what the plan actually promises.","cover":"plan-to-interior-render","order":1},{"id":"text-to-board","title":"Text → Presentation board","group":"gboards","what":"A structured text prompt produces a full presentation board — renders, drawings, diagrams, material palette — in one composition.","cover":"board-oma-community-centre","order":1},{"id":"image-to-elevation","title":"Image → Elevation","group":"g3d2d","what":"Extract flat, measured-style elevations from photos and renders of a building.","cover":"building-photo-to-front-side","order":2},{"id":"image-to-model-photo","title":"Image → Model photograph","group":"grender","what":"Re-present a design as a physical study model on a desk — millboard, PVC, layered topo — the language of the model shop.","cover":"landscape-to-desk-model-topo","order":2},{"id":"plan-to-axon","title":"Plan → Axonometric","group":"g2d3d","what":"Lift a plan into a measured three-dimensional projection while keeping its layout legible.","cover":"townhouse-plan-to-axon","order":2},{"id":"images-to-board","title":"Renders → Presentation board","group":"gboards","what":"Compose existing project images into a coherent competition-style board.","cover":"renders-to-library-board","order":2},{"id":"image-to-drawing-set","title":"Image → Drawing set","group":"g3d2d","what":"One image in, a coordinated set out: plan, section and elevation drawn as a consistent technical set.","cover":"render-to-drawing-set","order":3},{"id":"restyle-hand-media","title":"Render → Hand media","group":"grender","what":"Trade photorealism for hand media: watercolour washes, red-pen linework — the same design, a different voice.","cover":"render-to-watercolour","order":3},{"id":"section-to-view","title":"Section → Section perspective","group":"g2d3d","what":"Give a flat section depth: the cut stays a cut, but the space behind it opens into perspective or isometric.","cover":"section-to-section-perspective","order":3},{"id":"text-to-timeline","title":"Text → Timeline","group":"gboards","what":"Represent time: phasing, site history and design evolution as plan-view, collage or massing timelines.","cover":"timeline-high-line","order":3},{"id":"elevation-to-massing","title":"Elevation → Massing","group":"g2d3d","what":"Read a single orthographic elevation as the front face of a volume and build the massing it implies.","cover":"elevation-to-massing","order":4},{"id":"image-to-diagram","title":"Image → Diagram","group":"g3d2d","what":"Abstract an image into an argument: figure-ground, program, circulation and analysis diagrams.","cover":"render-to-figure-ground","order":4},{"id":"restyle-collage","title":"Render → Collage & flat illustration","group":"grender","what":"Push a render toward collage and flat graphic illustration — anti-photorealism as a deliberate register.","cover":"style-photoreal-to-collage","order":4},{"id":"image-to-axon","title":"Image → Axonometric","group":"g3d2d","what":"Re-project an image as a clean axonometric or exploded isometric illustration.","cover":"cad-to-exploded-axon","order":5},{"id":"sketch-to-massing","title":"Sketch → Massing study","group":"g2d3d","what":"A loose hand sketch becomes a clean massing study — early-stage ideation without losing the gesture.","cover":"sketch-to-massing-study","order":5},{"id":"edit-materials","title":"Swap materials","group":"grender","what":"Change what it is made of and nothing else: material swaps by prompt, precedent image, mood board or markup.","cover":"material-precedent-concrete","order":5},{"id":"edit-atmosphere","title":"Change atmosphere & season","group":"grender","what":"Same design, different weather: winter, night, rain — atmosphere as a controlled variable.","cover":"context-office-atmosphere","order":6},{"id":"contours-to-terrain","title":"Contours → Terrain","group":"g2d3d","what":"Read a topographic plan as a landform and render the terrain it describes.","cover":"contours-to-terrain","order":6},{"id":"drawing-to-cad","title":"Hand drawing → CAD linework","group":"g3d2d","what":"Clean a hand-drawn plan into precise CAD-style linework without redrawing it.","cover":"hand-drawn-plan-to-cad","order":6},{"id":"data-to-diagram","title":"Data → Diagram","group":"g3d2d","what":"Non-visual input becomes drawing: a species spreadsheet turns into tree-placement masterplan diagrams.","cover":"spreadsheet-to-tree-masterplan","order":7},{"id":"edit-populate","title":"Populate & place on site","group":"grender","what":"Bring the scene to life or move it to a real site: people, activity, vegetation, context.","cover":"context-villa-rainforest","order":7},{"id":"edit-canvas","title":"Clean up & extend","group":"grender","what":"Repair and grow the frame: remove clutter from site photos, outpaint beyond the canvas, redesign the street in place.","cover":"extend-canvas-outpaint","order":8},{"id":"change-view","title":"Same design → another view","group":"grender","what":"Move the camera, keep the project: exterior to aerial, exterior to interior, or a view from a marked point.","cover":"view-exterior-to-aerial","order":9}],"examples":[{"id":"aerial-to-linework-siteplan","group":"g3d2d","task":"image-to-plan","title":"Campus aerial photo → linework site plan","what":"Converts a UBC West Mall aerial photograph into a crisp black-and-white CAD-style site plan, preserving the exact layout while removing photographic texture, shadows, vehicles and people.","input":"An aerial photograph of UBC West Mall","prompt":"Transform the input aerial image into a clean technical black and white linework site plan drawing. Convert the image into precise architectural-style linework while preserving the exact layout, proportions, and spatial relationships from the original aerial view. Clearly represent roads, sidewalks, primary buildings, and trees using organized line hierarchy and simplified drafting conventions. Buildings should appear as solid clean outlines, roads and sidewalks should be clearly differentiated with consistent lineweights, and trees should be represented with minimal diagrammatic symbols appropriate for landscape plans. Remove photographic textures, shadows, colours, people, vehicles, and unnecessary visual noise. The final output should resemble a professional CAD or urban planning site plan with a crisp white background and refined black linework only.","parts":[{"k":"task","t":"Transform the input aerial image into a clean technical black and white linework site plan drawing"},{"k":"preserve","t":"preserve the exact layout, proportions, and spatial relationships from the original aerial view"},{"k":"style","t":"organized line hierarchy: buildings as solid outlines, roads/sidewalks differentiated by lineweight, trees as minimal diagrammatic symbols"},{"k":"change","t":"remove photographic textures, shadows, colours, people, vehicles, and visual noise"},{"k":"output","t":"a professional CAD or urban planning site plan, crisp white background, refined black linework only"}],"followups":[],"notes":[],"srcPage":"Technical Drawing (3D to 2D)","tier":"public","img":{"before":"content/examples/aerial-to-linework-siteplan/before.jpg","after":"content/examples/aerial-to-linework-siteplan/after.jpg"},"modes":["measured-drawing"]},{"id":"board-brooklyn-brownstone","group":"gboards","task":"text-to-board","title":"Text → A1 presentation board (Brooklyn brownstone renovation)","what":"A structured list-style prompt produces a full A1 board for a brownstone renovation — streetscape and interior renders, drawing set, exploded axon and material board — in a refined editorial layout.","input":"","prompt":"Design a vertical A1 architecture presentation board for a renovated Brooklyn brownstone in New York. Preserve the historic brick façade, stoop, and traditional proportions while introducing a warm mid-century modern interior renovation. Use rich walnut wood, natural stone, black steel accents, leather furniture, and large openings that bring natural light deep into the home. Include: – Exterior perspective from a characteristic Brooklyn streetscape showing the brownstone façade and tree-lined sidewalk – Interior rendering of the main living space featuring low-profile mid-century modern furniture, walnut millwork, statement lighting, warm textures, and views toward a rear garden – Floor plan, section, and elevation drawings in clean architectural linework – Axonometric diagram with exploded floor functions and subtle color coding – Material board featuring brick, walnut, natural stone, leather, brass, and black steel. Layout should be elegant, minimal, and highly graphic, with a white background, subtle shadows, modern sans-serif English annotations, and a refined editorial aesthetic. Inspired by contemporary Brooklyn townhouse renovations, mid-century modern interiors, and high-end architectural presentation boards.","parts":[{"k":"task","t":"Design a vertical A1 architecture presentation board for a renovated Brooklyn brownstone"},{"k":"preserve","t":"historic brick façade, stoop, and traditional proportions"},{"k":"change","t":"warm mid-century modern interior: walnut, natural stone, black steel, leather, large openings"},{"k":"output","t":"itemized board contents: exterior perspective, interior render, plan/section/elevation, exploded axon, material board"},{"k":"style","t":"elegant, minimal, highly graphic; white background, modern sans-serif annotations, editorial aesthetic"}],"followups":[],"notes":["The board contents are enumerated as a checklist — a reliable pattern for multi-panel outputs."],"srcPage":"Presentation Board","tier":"public","img":{"after":"content/examples/board-brooklyn-brownstone/after.jpg"},"modes":["board-layout","projection-systems","measured-drawing"]},{"id":"board-interior-renovation","group":"gboards","task":"images-to-board","title":"Interior photo → renovation presentation board","what":"Uses an existing interior photograph as the base, renovates the space with a cohesive design concept, and presents renders, detail views and a material palette as one polished board image.","input":"A photograph of the existing interior space to be renovated","prompt":"Using the attached interior image as the base, create a fully renovated version of the space and present the result as a single architectural presentation board. Reimagine the interior with a cohesive design concept while maintaining the overall spatial layout and proportions of the original space. Include photorealistic renderings of the renovated interior, detail views highlighting key design features, and a curated material palette that reflects the proposed aesthetic. Organize all content within a clean, minimalist layout featuring generous white space, modern typography, subtle graphic hierarchy, and a professional architectural presentation style. Use a white background and ensure the final output reads as a single polished presentation board image rather than a slideshow or multiple pages.","parts":[{"k":"task","t":"Create a fully renovated version of the attached interior and present it as a single presentation board"},{"k":"preserve","t":"maintain the overall spatial layout and proportions of the original space"},{"k":"change","t":"cohesive renovation concept; photorealistic renders, detail views, curated material palette"},{"k":"output","t":"one polished board image — not a slideshow or multiple pages; white background, minimalist layout, modern typography"}],"followups":[],"notes":[],"srcPage":"Presentation Board","tier":"public","img":{"before":"content/examples/board-interior-renovation/before.jpg","after":"content/examples/board-interior-renovation/after.jpg"},"modes":["board-layout"]},{"id":"board-oma-community-centre","group":"gboards","task":"text-to-board","title":"Text → A1 presentation board (OMA-style community centre)","what":"Generates an entire vertical A1 presentation board — masterplan, renders, elevations, axon and exploded program diagram — for an imagined OMA-style community centre from text alone.","input":"","prompt":"Create an architectural presentation board for a contemporary community centre in the style of OMA. The project features large public gathering spaces, flexible community programming, landscaped outdoor plazas, and a bold architectural form wrapped in a distinctive brise soleil façade system. The façade should act as a defining design feature, creating depth, shading, and a dynamic visual identity through patterned metal or vertical screening elements. Use a clean vertical A1 layout with a white background, subtle grid alignment, and strong graphic hierarchy. Include a top-down masterplan, photorealistic perspective renderings, building elevations highlighting the brise soleil system, an axonometric view, and an exploded program diagram with color-coded functions. Add floor plans with minimal linework, modern typography, and clear English annotations. Emphasize community engagement, circulation, environmental performance, and functional zoning through bold composition, analytical diagrams, and a contemporary OMA-inspired visual language.","parts":[{"k":"task","t":"Create an architectural presentation board for a contemporary community centre in the style of OMA"},{"k":"subject","t":"public gathering spaces, flexible programming, landscaped plazas, bold form wrapped in a brise soleil façade"},{"k":"output","t":"clean vertical A1 layout, white background, subtle grid alignment, strong graphic hierarchy; masterplan + renders + elevations + axon + exploded program diagram + floor plans"},{"k":"style","t":"modern typography, clear English annotations, contemporary OMA-inspired visual language"}],"followups":[],"notes":["Text→image: no input image — the board layout, drawing types and graphic language are all specified in the prompt."],"srcPage":"Presentation Board","tier":"public","img":{"after":"content/examples/board-oma-community-centre/after.jpg"},"modes":["board-layout","projection-systems","diagram"]},{"id":"board-street-renovation","group":"gboards","task":"text-to-board","title":"Text → landscape board (street renovation)","what":"A fully structured section-by-section prompt (site plan / perspective / street section / technical diagrams / material palette / presentation style) generates a competition-quality A1 street renovation board.","input":"","prompt":"Generate a vertical A1 architecture presentation board for a street renovation and landscape design project. Site Plan: Show the redesigned street layout integrated into the existing urban context. Include sidewalks, planting zones, street furniture, and roadway organization. Use clear hierarchy, annotations, and clean urban design graphics. Perspective Rendering: Include a photorealistic street-level rendering of the revitalized public realm. Show paving, planting, pedestrians, and surrounding buildings. Emphasize a vibrant, walkable, and comfortable streetscape. Street Section: Provide a detailed cross-section showing lane divisions, sidewalks, planting zones, and bioswales. Annotate key dimensions, materials, and landscape elements. Clearly illustrate stormwater management strategies. Technical Diagrams: Include diagrams explaining permeable paving, bioswales, and drainage systems. Use exploded views or simplified axonometrics. Clearly communicate environmental performance. Material Palette & Details: Show paving materials, curbs, tree pits, and planting palettes. Include zoomed-in vignettes of benches, lighting, and curb transitions. Label materials and construction components clearly. Presentation Style: Use soft colors, clean linework, and minimalist typography. Maintain a balanced layout with generous white space. Create a professional, competition-quality presentation board.","parts":[{"k":"task","t":"Generate a vertical A1 presentation board for a street renovation and landscape design project"},{"k":"output","t":"named sections: site plan, perspective rendering, street section, technical diagrams, material palette & details"},{"k":"subject","t":"bioswales, permeable paving, stormwater management, planting zones, street furniture"},{"k":"style","t":"soft colors, clean linework, minimalist typography, generous white space, competition quality"}],"followups":[],"notes":["Each board panel gets its own labelled paragraph — the prompt is effectively a board layout specification."],"srcPage":"Landscape Design Board","tier":"public","img":{"after":"content/examples/board-street-renovation/after.jpg"},"modes":["board-layout","diagram","measured-drawing"]},{"id":"board-waterfront-renewal","group":"gboards","task":"text-to-board","title":"Text → landscape board (waterfront renewal & erosion mitigation)","what":"The same structured board grammar applied to a waterfront renewal project: bird's-eye masterplan, shoreline section with root systems, resilience diagrams and a native-species palette.","input":"","prompt":"Generate a image of a vertical A1 landscape architecture presentation board for a waterfront renewal and erosion mitigation project. Site Plan: Create a photorealistic bird's-eye view master plan of the waterfront. Show planting strategies, shoreline stabilization measures, pathways, and new public realm additions. Use clear annotations, hierarchy, and labels to communicate key interventions. Perspective Rendering: Include a photorealistic eye-level rendering from a waterfront sidewalk. Show native planting, shoreline improvements, public seating, and pedestrian activity. Emphasize the relationship between people, landscape, and water. Waterfront Section: Create a detailed section through the shoreline. Illustrate vegetation root systems, erosion control measures, and added infrastructure. Clearly show how the design improves shoreline resilience and ecological performance. Technical Diagrams: Include diagrams explaining ground surface health, drainage systems, and stormwater management. Visualize water movement, infiltration, and erosion mitigation strategies. Clearly communicate environmental performance and long-term resilience. Material Palette: Showcase native plant species used throughout the project. Include materials for shoreline infrastructure, pathways, edging, and site furnishings. Provide concise labels and texture samples. Presentation Style: Use a modern, minimal, and professional graphic language. Maintain a balanced layout with clean linework, subtle colors, and generous white space. Create a cohesive competition-quality presentation board suitable for design review.","parts":[{"k":"task","t":"Generate a vertical A1 landscape architecture board for a waterfront renewal and erosion mitigation project"},{"k":"output","t":"sections: bird's-eye master plan, eye-level perspective, shoreline section, technical diagrams, native-species material palette"},{"k":"subject","t":"shoreline stabilization, root systems, erosion control, infiltration, ecological resilience"},{"k":"style","t":"modern, minimal graphic language; clean linework, subtle colors, generous white space"}],"followups":[],"notes":[],"srcPage":"Landscape Design Board","tier":"public","img":{"after":"content/examples/board-waterfront-renewal/after.jpg"},"modes":["board-layout","diagram","mapping"]},{"id":"building-photo-to-front-side","group":"g3d2d","task":"image-to-elevation","title":"Building photo → front and side elevations (drawing style)","what":"The same task with the output style tightened: elevations presented in a clear architectural drawing style on a white or neutral background.","input":"A photograph of a building","prompt":"Based on the photo, generate front and side views of the building. Present the elevations with a white or neutral background, using a clear architectural drawing style.","parts":[{"k":"task","t":"Based on the photo, generate front and side views of the building"},{"k":"style","t":"clear architectural drawing style"},{"k":"output","t":"white or neutral background"}],"followups":[],"notes":[],"srcPage":"Front and Side View","tier":"public","img":{"before":"content/examples/building-photo-to-front-side/before.jpg","after":"content/examples/building-photo-to-front-side/after.jpg"},"modes":["measured-drawing"]},{"id":"cad-to-exploded-axon","group":"g3d2d","task":"image-to-axon","title":"Rhino screenshot → exploded isometric assembly diagram","what":"Turns a Rhino model screenshot of the cafe project into an exploded isometric assembly drawing, separating structural systems, floors, roof and facade while staying strictly consistent with the modelled geometry.","input":"A Rhino viewport screenshot of the waffle-roof cafe model","prompt":"Transform the input Rhino model into a clean exploded isometric assembly drawing in a technical architectural diagram style. The output must remain fully consistent with the original model — preserve the exact building design, geometry, proportions, scale, and overall form without reinterpretation or alteration. Separate the major building components vertically and logically to clearly communicate how the project is assembled while maintaining precise alignment between all exploded elements. Use even spacing and organized layering to improve readability while ensuring the exploded view still accurately represents the original building. Render the drawing in clean black and white linework with minimal shading on a white background, similar to a professional CAD or axonometric construction diagram. Clearly distinguish structural systems, floors, roofs, facade elements, and key assemblies through line hierarchy and subtle tonal variation while avoiding photorealistic rendering. The final image should feel precise, technically accurate, and presentation-quality.","parts":[{"k":"task","t":"Transform the input Rhino model into a clean exploded isometric assembly drawing"},{"k":"preserve","t":"remain fully consistent with the original model — exact design, geometry, proportions, scale and form, no reinterpretation"},{"k":"change","t":"separate major components vertically and logically with even spacing and precise alignment between exploded elements"},{"k":"style","t":"clean black and white linework, minimal shading, white background; distinguish structure, floors, roofs and facade through line hierarchy"},{"k":"negative","t":"avoid photorealistic rendering"}],"followups":[],"notes":[],"srcPage":"Technical Drawing (3D to 2D)","tier":"public","img":{"before":"content/examples/cad-to-exploded-axon/before.jpg","after":"content/examples/cad-to-exploded-axon/after.jpg"},"modes":["projection-systems","diagram"]},{"id":"circulation-overlay","group":"g3d2d","task":"image-to-diagram","title":"Render → circulation overlay","what":"Draws movement onto an existing view as a graphic overlay, keeping the image underneath intact. Explains how people flow through a scheme without a new drawing.","input":"An aerial or eye-level render of a building and its approach, entrances visible","prompt":"Overlay a circulation diagram onto this render. The render itself is not repainted or altered; it may only be desaturated to about 40 percent so the overlay reads. Draw the primary route as one bold continuous red line following the actual paths and doors, secondary routes as thinner dashed lines in the same red, and each entrance as a small solid circle. Clean vector-like graphics with consistent line weight, lines sitting flat on the image plane with rounded corners at direction changes. One image, same crop as the input, no text or arrowhead clutter beyond a single arrowhead at each route end.","parts":[{"k":"task","t":"Overlay a circulation diagram onto this render"},{"k":"preserve","t":"the render is not repainted or altered; it may only be desaturated to about 40 percent so the overlay reads"},{"k":"change","t":"primary route as one bold continuous red line following actual paths and doors; secondary routes as thinner dashed lines; entrances as small solid circles"},{"k":"style","t":"clean vector-like graphics, consistent line weight, rounded corners at direction changes"},{"k":"output","t":"one image, same crop as the input, a single arrowhead at each route end"}],"followups":["Add a second colour for vehicle circulation on the road only; pedestrian lines unchanged","Thin all lines by half and lighten the desaturation; routes stay exactly where they are","Remove secondary routes, leaving only the primary line and entrance dots"],"notes":["Overlay lines happily pass through walls and hedges — trace each route against real doors and paths","The base image gets restyled instead of just dimmed; compare the underlying render before and after","Line weight wobbles along a single route, reading as multiple hierarchies; demand one consistent weight"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["notation-scores","perspective-view"]},{"id":"cleanup-site-photo","group":"grender","task":"edit-canvas","title":"Clean up a site photo","what":"Removes clutter from a survey photograph so it can serve as a clean base for proposals. Everything you keep must stay pixel-faithful, or the base is worthless.","input":"A street-level site photograph with parked cars, overhead wires, wheelie bins and temporary fencing","prompt":"Remove the parked cars, overhead wires, wheelie bins and temporary fencing from this site photograph. Everything else stays pixel-faithful: buildings, paving pattern, kerb lines, trees, sky and lighting untouched outside the removed regions. Fill the cleared areas by plausibly continuing what sits behind them, extending the paving joints, kerbs and facade bases through where the objects stood. One photograph, same crop, same colour balance. Do not beautify the scene, do not clean the existing weathering or graffiti, do not add anything new.","parts":[{"k":"task","t":"Remove the parked cars, overhead wires, wheelie bins and temporary fencing from this site photograph"},{"k":"preserve","t":"everything else pixel-faithful: buildings, paving, kerbs, trees, sky, lighting untouched outside the removed regions"},{"k":"change","t":"fill cleared areas by plausibly continuing what sits behind them — paving joints, kerbs, facade bases run through"},{"k":"output","t":"one photograph, same crop, same colour balance as the original"},{"k":"negative","t":"do not beautify, do not clean weathering or graffiti, do not add anything new"}],"followups":["Also remove the road markings; kerbs and paving must not shift","Slightly overcast the sky to flatten harsh shadows; buildings and ground untouched","Extend this cleaned photo 20 percent to the right, continuing the street"],"notes":["Models improve regions you never touched — run a difference check between input and output","Infill behind removed objects repeats cloned texture; look for stamped patterns in paving and facades","Shadows of removed objects survive their owners; hunt for orphan shadows on the ground"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["perspective-view"]},{"id":"context-cafe-human-activity","group":"grender","task":"edit-populate","title":"Cafe render → populated with human activity","what":"Adds believable human life — walkers, cyclists, patio couples, a short queue inside — to an empty cafe render without touching the architecture, composition or camera.","input":"A finished but unpopulated cafe render","prompt":"Add realistic human activity throughout the cafe render while maintaining the exact architecture, composition, and camera angle of the original image. Include people walking and biking along the sidewalk, couples sitting on the patio having drinks and conversing, and a short, casual lineup inside the cafe near the counter. The atmosphere should feel warm, welcoming, comfortable, and socially active without appearing overcrowded. Ensure all people, lighting, shadows, and interactions are integrated naturally into the scene with a photorealistic quality that matches the render.","parts":[{"k":"task","t":"Add realistic human activity throughout the cafe render"},{"k":"preserve","t":"maintain the exact architecture, composition, and camera angle of the original image"},{"k":"change","t":"people walking and biking along the sidewalk, couples on the patio, a short casual lineup inside near the counter"},{"k":"style","t":"warm, welcoming, socially active without appearing overcrowded; people, lighting and shadows integrated photorealistically"}],"followups":[],"notes":[],"srcPage":"Adding Context (1)","tier":"public","img":{"before":"content/examples/context-cafe-human-activity/before.jpg","after":"content/examples/context-cafe-human-activity/after.jpg"},"modes":["perspective-view"]},{"id":"context-office-atmosphere","group":"grender","task":"edit-atmosphere","title":"Office render → winter / night / rain atmospheres","what":"Re-renders one office building under three atmospheres — winter snow, night-time interior glow, and rainy gloom — with the architecture, composition and camera locked in every variant.","input":"A starting office building render","prompt":"Transform the render into a winter setting while preserving the exact architecture, composition, and camera angle of the original image. Add a light layer of realistic snow accumulation on the rooftops, surrounding landscape, sidewalks, and roads while keeping the roads partially visible and functional. The trees should appear winter-like with sparse foliage or light snow coverage on branches. Adjust the lighting and atmosphere to create a cold but inviting seasonal mood with soft winter daylight and realistic reflections, shadows, and snow textures to maintain a photorealistic quality.","parts":[{"k":"task","t":"Transform the render into a winter setting"},{"k":"preserve","t":"preserve the exact architecture, composition, and camera angle"},{"k":"change","t":"light realistic snow on rooftops, landscape, sidewalks and roads — roads stay partially visible and functional; winter-like trees"},{"k":"light","t":"cold but inviting seasonal mood, soft winter daylight, realistic reflections, shadows and snow textures"}],"followups":["Transform the render into a nighttime scene while preserving the exact architecture, composition, and surrounding context of the original image. Illuminate the interior of the building with a soft warm glow that contrasts against the darker exterior environment. Through the windows, show subtle silhouettes of people working, moving, and occupying the space to create a sense of life and activity without overcrowding the scene. Enhance reflections, interior lighting gradients, and atmospheric shadows to create a cozy, inviting, and photorealistic nighttime architectural render.","Transform the render into a rainy, gloomy weather condition while preserving the exact architecture, composition, and overall scene layout. Add overcast skies, soft foggy atmosphere, wet pavement, puddles, and realistic rain effects to create a moody environment. Enhance reflections on roads, sidewalks, and glass surfaces from the wet conditions while slightly muting the overall colour palette to emphasize the gloomy atmosphere. The building should remain visually prominent and realistic within the scene, with subtle interior lighting and atmospheric depth maintaining a photorealistic architectural render quality."],"notes":["One sub-example, three atmosphere prompts (season, time of day, weather). Step images show the night and rain variants."],"srcPage":"Adding Context (1)","tier":"public","img":{"before":"content/examples/context-office-atmosphere/before.jpg","after":"content/examples/context-office-atmosphere/after.jpg","steps":["content/examples/context-office-atmosphere/step1.jpg","content/examples/context-office-atmosphere/step2.jpg"]},"modes":["perspective-view"]},{"id":"context-pavilion-trout-lake","group":"grender","task":"edit-populate","title":"Pavilion render → placed at Trout Lake (real site)","what":"Places a finished pavilion design into the real context of Trout Lake / John Hendry Park using two site reference photos, keeping the pavilion's form and materiality exact.","input":"A starting pavilion render, plus two reference photos of Trout Lake / John Hendry Park, Vancouver","prompt":"Use the attached pavilion design and place it realistically within the context of Trout Lake (John Hendry Park) using the reference images provided. Position the pavilion along the lake edge so it overlooks the water with clear sightlines across the lake. Maintain the exact pavilion form, proportions, and materiality while integrating it naturally into the surrounding landscape, pathways, trees, and shoreline conditions of the park.","parts":[{"k":"task","t":"Place the attached pavilion design realistically within the context of Trout Lake (John Hendry Park) using the reference images provided"},{"k":"camera","t":"position the pavilion along the lake edge so it overlooks the water with clear sightlines across the lake"},{"k":"preserve","t":"maintain the exact pavilion form, proportions, and materiality"},{"k":"change","t":"integrate it naturally into the surrounding landscape, pathways, trees, and shoreline conditions of the park"}],"followups":[],"notes":["RA's framing: adding real-world context as the FINAL step keeps the core design consistent — separating context generation from design generation minimizes distortion of the architecture."],"srcPage":"Adding Context (1)","tier":"public","img":{"before":"content/examples/context-pavilion-trout-lake/before.jpg","after":"content/examples/context-pavilion-trout-lake/after.jpg"},"modes":["perspective-view"]},{"id":"context-villa-rainforest","group":"grender","task":"edit-populate","title":"Villa render → tropical rainforest context (+ markup fig tree)","what":"Swaps the surroundings of a villa render for a dense tropical rainforest using a reference image as inspiration only, then places a specific fig tree at a marked-up location as a refinement.","input":"A starting villa render, plus a tropical forest reference image (inspiration only)","prompt":"Transform the surrounding context of the villa into a dense tropical rainforest environment with lush vegetation, layered jungle planting, large tropical trees, vines, palms, and humid atmospheric lighting. The villa should feel immersed within the rainforest while maintaining the exact architectural form, proportions, and materials of the original render. The front approach of the home must remain functional and realistic, with a paved driveway and accessible arrival sequence integrated naturally into the landscape. Use the attached reference image only as inspiration for the tree species, vegetation density, and rainforest atmosphere — do not directly copy or use the exact background composition from the reference image. The final output should be a highly detailed photorealistic architectural render with realistic lighting, shadows, textures, and environmental depth.","parts":[{"k":"task","t":"Transform the surrounding context of the villa into a dense tropical rainforest environment"},{"k":"preserve","t":"maintain the exact architectural form, proportions, and materials of the original render; the front approach must remain functional with a paved driveway"},{"k":"change","t":"lush vegetation, layered jungle planting, large tropical trees, vines, palms, humid atmospheric lighting"},{"k":"negative","t":"use the reference image only as inspiration for species, density and atmosphere — do not copy its background composition"},{"k":"output","t":"highly detailed photorealistic render with realistic lighting, shadows, textures, environmental depth"}],"followups":["Place the attached fig tree within the render at the exact location indicated by the drawn line. Integrate the tree naturally into the scene while maintaining realistic scale and proportions relative to the architecture and surrounding landscape. Adjust the tree's lighting, shadows, colour tones, and atmospheric depth so it blends seamlessly with the render and matches the existing environmental conditions and overall photorealistic quality of the image."],"notes":["The refinement combines three control channels at once: a follow-up prompt, a reference image (the fig tree), and markup (a drawn line marking placement). Step images show the markup input and the final placement."],"srcPage":"Adding Context (1)","tier":"public","img":{"before":"content/examples/context-villa-rainforest/before.jpg","after":"content/examples/context-villa-rainforest/after.jpg","steps":["content/examples/context-villa-rainforest/step1.jpg","content/examples/context-villa-rainforest/step2.jpg"]},"modes":["perspective-view"]},{"id":"contours-to-terrain","group":"g2d3d","task":"contours-to-terrain","title":"Contour map → terrain view","what":"Reads a topographic plan as a landform and renders the terrain in perspective. Essential for landscape students checking whether a grading strategy actually produces the landform intended.","input":"A topographic plan with contour lines at 1 m intervals, a stream corridor in the valley and a flat plateau marked at the top","prompt":"Convert this contour plan into a perspective view of the actual terrain it describes. Keep the ridgeline positions, the valley alignment and the plateau location exactly as the contours place them; slope steepness must follow contour spacing. Render the landform as mown and meadow grass with exposed rock only on the steepest faces, and the stream following the drawn corridor at the valley floor. Low aerial oblique from the downhill side looking up the valley. Low sun from the side so the landform reads through shadow. One photorealistic terrain image, no buildings, no roads, no text.","parts":[{"k":"task","t":"Convert this contour plan into a perspective view of the actual terrain it describes"},{"k":"preserve","t":"ridgeline positions, valley alignment and plateau location exactly as the contours place them; slope steepness follows contour spacing"},{"k":"change","t":"render the landform as mown and meadow grass with exposed rock on the steepest faces, the stream following the drawn corridor"},{"k":"camera","t":"low aerial oblique from the downhill side looking up the valley, horizon in the top fifth of the frame"},{"k":"light","t":"low sun from the side so the landform reads through shadow, clear sky"},{"k":"negative","t":"no buildings, no roads, no text"}],"followups":["Same terrain and camera, but render it in winter with light snow holding on north-facing slopes","Add a single switchback path climbing the steep face at a walkable gradient; touch nothing else","Move the camera to the plateau looking down the valley; the landform must not change"],"notes":["Contours get treated as surface decoration rather than elevation data — check that valleys are low and ridges are high, inversions are common","Vertical scale is usually exaggerated for drama; state the contour interval and ask for true proportion","The stream may wander off its drawn corridor or run uphill; trace it against the plan"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["mapping","perspective-view"]},{"id":"elevation-to-massing","group":"g2d3d","task":"elevation-to-massing","title":"Elevation → volumetric massing","what":"Uses a single orthographic elevation as the front face of a three-dimensional volume, so you can judge how the facade composition reads in the round.","input":"A street elevation drawing of a mid-rise facade, orthographic, with a regular window grid and parapet line","prompt":"Use this elevation drawing as the front face of a simple building volume and show the building in three-quarter exterior view. Keep the bay rhythm, storey count, opening proportions and parapet height exactly as drawn on the front face. Give the volume a depth of roughly half its width; treat the side and rear faces as plain rendered surfaces with no openings so attention stays on the drawn facade. Three-quarter view from street level, about 20 m back, slight upward tilt, the whole building in frame. Morning sun raking across the facade from the left. One image, neutral paved foreground, plain sky, no signage or text.","parts":[{"k":"task","t":"Use this elevation drawing as the front face of a simple building volume and show the building in three-quarter exterior view"},{"k":"preserve","t":"keep the bay rhythm, storey count, opening proportions and parapet height exactly as drawn on the front face"},{"k":"change","t":"give the volume a depth of roughly half its width; side and rear faces plain with no openings"},{"k":"camera","t":"three-quarter view from street level, about 20 m back, slight upward tilt, whole building in frame"},{"k":"light","t":"morning sun raking across the facade from the left to reveal reveal depths and shadow lines"},{"k":"output","t":"one image, neutral paved foreground, plain sky, no signage or text"}],"followups":["Repeat the window grid on the visible side face at the same rhythm; change nothing on the front","Deepen the window reveals to about 300 mm; keep the grid and proportions frozen","Show the same volume from the opposite corner under the same light"],"notes":["The model redesigns the facade while extruding it — verify the bay count and opening proportions","Invented rooftop plant, railings and setbacks appear above the parapet; forbid them if unwanted","Side faces get fully glazed by default; specify how the unseen faces should be treated"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["measured-drawing"]},{"id":"extend-canvas-outpaint","group":"grender","task":"edit-canvas","title":"Extend the canvas (outpainting)","what":"Widens an image beyond its original frame, inventing consistent context on both sides. Rescues renders cropped too tight for a board or a wide-format panel.","input":"A render or photo of a building that is cropped too tightly, with the context cut off at both edges","prompt":"Extend this image to the left and right until it is twice as wide, continuing the scene beyond the original frame. The original image area stays exact and unedited at the centre; the horizon height, vanishing points, lighting direction and colour balance continue seamlessly. Continue the street logically: neighbouring buildings of similar height and grain, pavement and kerb lines running on, planting consistent with what exists. One wide image at 2:1 of the original width, no visible seams. No landmarks, no dramatic new focal buildings, nothing that competes with the original subject.","parts":[{"k":"task","t":"Extend this image to the left and right until it is twice as wide, continuing the scene beyond the original frame"},{"k":"preserve","t":"the original image area stays exact and unedited at the centre; horizon, vanishing points, lighting and colour balance continue seamlessly"},{"k":"change","t":"continue the street logically: neighbouring buildings of similar height and grain, pavement and kerbs running on, consistent planting"},{"k":"output","t":"one wide image at 2:1 of the original width, no visible seams"},{"k":"negative","t":"no landmarks, no dramatic new focal buildings, nothing that competes with the original subject"}],"followups":["Extend upward by 30 percent to gain sky for board text placement; sides and centre untouched","Calm the left extension: simpler facades, fewer openings; the right side stays","Continue one more step wider on the right only, holding everything already generated"],"notes":["Seams show as subtle shifts in grain, colour or perspective at the old frame line — zoom in along that boundary","New context contradicts the vanishing points and the ground plane tilts; check kerbs and rooflines with a ruler","Outpainting loves to duplicate the main building as its own neighbour; forbid lookalike structures"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["perspective-view"]},{"id":"hand-drawn-plan-to-cad","group":"g3d2d","task":"drawing-to-cad","title":"Hand-drawn site plan → clean CAD linework","what":"Converts a hand-drawn landscape site plan into a single-lineweight vector-style CAD drawing, replacing sketch textures with clean outlines and trees with canopy circles.","input":"A hand-drawn landscape site plan (pen/pencil sketch photo)","prompt":"Convert this hand-drawn landscape site plan into a clean technical CAD drawing. Use a single, consistent thin line weight throughout and remove all sketch textures, shading, hatching, and artistic effects. Retain only clear vector-style outlines for buildings, paths, planting beds, lawns, curbs, ROWs, and other site elements. Replace all trees with simple line circles sized to represent canopy extents, and show shrubs as smaller circles or ovals. Ensure all geometry is crisp, accurate, and professionally drafted, with smooth curves and clean connections. Use black linework on a white background only. The final drawing should resemble an AutoCAD or Illustrator site plan and be suitable for further editing.","parts":[{"k":"task","t":"Convert this hand-drawn landscape site plan into a clean technical CAD drawing"},{"k":"style","t":"single consistent thin line weight, black linework on white only, AutoCAD/Illustrator site-plan appearance"},{"k":"change","t":"remove sketch textures, shading, hatching and artistic effects; trees become line circles sized to canopy extents, shrubs smaller circles or ovals"},{"k":"preserve","t":"clear outlines for buildings, paths, planting beds, lawns, curbs, ROWs and other site elements; crisp, accurate geometry"}],"followups":[],"notes":[],"srcPage":"Photo to Elevation (or CAD)","tier":"public","img":{"before":"content/examples/hand-drawn-plan-to-cad/before.jpg","after":"content/examples/hand-drawn-plan-to-cad/after.jpg"},"modes":["measured-drawing","sketch"]},{"id":"interior-photo-to-section","group":"g3d2d","task":"image-to-drawing-set","title":"Interior photo → measured-style section","what":"Reconstructs a drawn cross-section from an interior photograph, turning experienced space back into drawing convention. Strong exercise for understanding how sections encode space.","input":"A wide interior photograph of a double-height space with a mezzanine, taken roughly perpendicular to the long wall","prompt":"Reconstruct this interior photograph as a measured-style orthographic cross-section through the space. Keep the proportion of height to width, the mezzanine level, the ceiling profile and the window positions on the far wall as the photo shows them. Cut the section where the camera stands: draw cut walls, floor slabs and roof as solid black poché, and the far wall beyond the cut as a fine-line interior elevation. Architectural section convention, black poché, fine grey interior lines, a single human figure at 1.7 m for scale. One flat orthographic drawing on white, no perspective, no photo texture, no text.","parts":[{"k":"task","t":"Reconstruct this interior photograph as a measured-style orthographic cross-section through the space"},{"k":"preserve","t":"proportion of height to width, mezzanine level, ceiling profile, window positions on the far wall"},{"k":"change","t":"cut the section at the camera position: cut walls, slabs and roof as solid black poché, the far wall as fine-line interior elevation"},{"k":"style","t":"section convention, black poché, fine grey interior lines, one human figure at 1.7 m for scale"},{"k":"output","t":"one flat orthographic drawing on white, no perspective, no photo texture, no text"}],"followups":["Add the furniture visible in the photo as fine outline only; poché and walls untouched","Thicken the roof buildup to show a plausible construction depth; spatial proportions frozen","Render the same section with a soft grey shadow wash to show daylight direction"],"notes":["Wide-angle lens distortion becomes wrong proportion in the drawing — the space usually comes out too tall","Slab and wall thicknesses are pure invention; treat the poché as diagrammatic, not measurable","Elements behind the camera get imagined into the cut; state that the cut is at the camera position"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["measured-drawing"]},{"id":"landscape-to-desk-model-topo","group":"grender","task":"image-to-model-photo","title":"Terrain model → layered topographic desk model","what":"Converts a digital contour terrain model into a stepped topographic study model of stacked millboard sheets, with dried baby's breath standing in for trees.","input":"A digital 3D contour/terrain model image of a sloped landscape site","prompt":"Convert the landscape from the reference image into a small-scale topographic architectural model. Represent the landform as a layered stepped model, with contour levels expressed through stacked sheets of beige millboard to create a warm, organic appearance. Include key site features and vegetation, using dried baby's breath to represent trees and larger planting areas. Place the model on a clean white base and present it within an architectural studio setting. Include model-making tools, cutting mats, and landscape design materials nearby. Use soft natural lighting, subtle shadows, and a contemporary studio atmosphere to create a realistic handcrafted landscape model display.","parts":[{"k":"task","t":"Convert the landscape from the reference image into a small-scale topographic architectural model"},{"k":"change","t":"represent the landform as a layered stepped model, contour levels as stacked sheets of beige millboard; dried baby's breath for trees and planting areas"},{"k":"style","t":"clean white base, architectural studio setting with tools, cutting mats and landscape design materials"},{"k":"light","t":"soft natural lighting, subtle shadows, contemporary studio atmosphere"}],"followups":[],"notes":[],"srcPage":"Photo to Model on Desk","tier":"public","img":{"before":"content/examples/landscape-to-desk-model-topo/before.jpg","after":"content/examples/landscape-to-desk-model-topo/after.jpg"},"modes":["model-photography","mapping"]},{"id":"massing-to-program-axon","group":"g3d2d","task":"image-to-diagram","title":"Massing render → colour-coded program axonometric","what":"Divides a building massing into labelled colour-coded program blocks (retail / office / residential) plus a second axon of carved voids and circulation, in a competition-board diagram style.","input":"A render of an office building massing","prompt":"Transform the building massing into a clean axonometric program diagram. Divide the volume into color-coded 3D blocks representing different programmatic functions (ex. Retail, Office, Residential), with each block clearly labeled using large, bold typography embedded within the geometry. Use bright, contrasting colors to distinguish functions while maintaining a minimal architectural graphic style. Alongside the primary diagram, create a second axonometric diagram showing key programmatic voids, circulation spaces, courtyards, gardens, cultural spaces, or passages carved from the same massing. Maintain precise linework, minimal black outlines, no shadows, and a pure white background. The final graphic should feel conceptual, academic, and presentation-ready, similar to diagrams found in architecture competition boards and design publications.","parts":[{"k":"task","t":"Transform the building massing into a clean axonometric program diagram"},{"k":"change","t":"divide the volume into color-coded 3D blocks by programmatic function, labelled with large bold typography embedded in the geometry; add a second axon of programmatic voids, circulation, courtyards and passages carved from the same massing"},{"k":"style","t":"bright contrasting colors, minimal architectural graphic style, precise linework, minimal black outlines, no shadows, pure white background"},{"k":"output","t":"conceptual, academic, presentation-ready — like competition-board diagrams"}],"followups":[],"notes":[],"srcPage":"Photo/Plan to Isometric Diagram","tier":"public","img":{"before":"content/examples/massing-to-program-axon/before.jpg","after":"content/examples/massing-to-program-axon/after.jpg"},"modes":["projection-systems","diagram","notation-scores"]},{"id":"material-kitchen-moodboard","group":"grender","task":"edit-materials","title":"Kitchen render → material palette from a mood board","what":"Transfers the wood and stone palette of an attached Pinterest mood board onto an existing kitchen render — cabinetry, backsplash, counters and ceiling each mapped to a named material — without altering the design.","input":"An AI-generated kitchen render, plus a Pinterest mood board of wood and stone materials","prompt":"Apply the material palette from the attached mood board directly onto the existing kitchen render while preserving the exact composition, geometry, camera angle, lighting, and layout of the original image. Do not alter the structure, furniture placement, or design of the kitchen. Use the wood material from the mood board on all cabinetry surfaces, ensuring the tone, grain, warmth, and finish closely match the reference material. Apply the darker stone material from the mood board to the backsplash surfaces to create depth and contrast, while using the lighter stone for the countertops and kitchen island surfaces for a softer and more refined appearance. The ceiling should be clad with the lightest stone material from the mood board, creating a clean and cohesive overhead surface. Maintain the exact texture, veining, colour variation, and finish shown in the references so the materials feel realistic and architecturally integrated. Ensure the overall palette remains warm, balanced, and contemporary. The sole purpose of this edit is to transfer the materiality from the mood board onto the kitchen render without changing any other elements.","parts":[{"k":"task","t":"Apply the material palette from the attached mood board directly onto the existing kitchen render"},{"k":"preserve","t":"exact composition, geometry, camera angle, lighting and layout; do not alter structure, furniture placement or design"},{"k":"change","t":"mood-board wood on all cabinetry; darker stone on backsplash; lighter stone on counters and island; lightest stone cladding the ceiling"},{"k":"style","t":"match the exact texture, veining, colour variation and finish of the references; warm, balanced, contemporary"},{"k":"output","t":"sole purpose is to transfer materiality — nothing else changes"}],"followups":[],"notes":["Listed under “For Greater Control” — a mood board pins down material intent more reliably than adjectives."],"srcPage":"Controlling Materiality (1)","tier":"public","img":{"before":"content/examples/material-kitchen-moodboard/before.jpg","after":"content/examples/material-kitchen-moodboard/after.jpg"},"modes":["perspective-view"]},{"id":"material-markup-mesh","group":"grender","task":"edit-materials","title":"Markup circles → mesh facade on selected surfaces only","what":"Uses circled markup on the input render to confine a new white honeycomb-perforated metal mesh facade to specific building surfaces, leaving everything outside the circles untouched.","input":"A building render with the target facade zones circled in markup","prompt":"Add a white metal mesh secondary facade onto only the circled portions of the building while preserving the exact geometry, composition, camera angle, structure, and surrounding context of the original render. The facade should consist of a clean honeycomb perforation pattern with a contemporary architectural appearance, allowing partial transparency and light filtration through the mesh. The material should feel lightweight and refined with a matte white metal finish. Ensure the mesh wraps naturally and realistically onto the selected surfaces without altering the underlying building form. Do not add or remove any architectural elements outside of the circled regions. The sole purpose of this edit is to apply the white honeycomb-patterned mesh facade onto the specified areas while maintaining the overall architectural integrity of the original render.","parts":[{"k":"task","t":"Add a white metal mesh secondary facade onto only the circled portions of the building"},{"k":"preserve","t":"exact geometry, composition, camera angle, structure and surrounding context; the mesh must not alter the underlying building form"},{"k":"style","t":"clean honeycomb perforation, partial transparency and light filtration, lightweight matte white metal finish"},{"k":"negative","t":"do not add or remove any architectural elements outside of the circled regions"}],"followups":[],"notes":["Markup (specific material placement) — the circles do the spatial targeting that words alone cannot."],"srcPage":"Controlling Materiality (1)","tier":"public","img":{"before":"content/examples/material-markup-mesh/before.jpg","after":"content/examples/material-markup-mesh/after.jpg"},"modes":["perspective-view"]},{"id":"material-precedent-concrete","group":"grender","task":"edit-materials","title":"Precedent reference → cast white concrete pavilion","what":"Replaces the wooden surfaces of a pavilion render with sculptural cast white concrete, using MAD Architects' Wormhole Library as the attached material precedent.","input":"An AI-generated pavilion render, plus a photo of the Wormhole Library by MAD Architects as material precedent","prompt":"Apply a casted white concrete material inspired by the smooth sculptural surfaces of MAD Architects' Wormhole Library onto all existing wooden portions of the pavilion render while preserving the exact geometry, structure, proportions, composition, lighting, and surrounding context of the original image. The new material should feel monolithic, soft, and fluid with a refined matte finish and subtle concrete texture rather than rough industrial concrete. Maintain the curved and organic architectural qualities of the pavilion so the material appears seamlessly cast and integrated into the form. Do not alter the design, scale, or spatial arrangement of the pavilion in any way. The sole purpose of this edit is to replace the wood material with sculptural white casted concrete while maintaining the original architectural intent and atmosphere of the render.","parts":[{"k":"task","t":"Apply a casted white concrete material inspired by MAD Architects' Wormhole Library onto all existing wooden portions of the pavilion render"},{"k":"preserve","t":"exact geometry, structure, proportions, composition, lighting and surrounding context; do not alter design, scale or spatial arrangement"},{"k":"style","t":"monolithic, soft, fluid, refined matte finish with subtle concrete texture — not rough industrial concrete"},{"k":"output","t":"sole purpose: replace wood with sculptural white cast concrete, keeping the original intent and atmosphere"}],"followups":[],"notes":["Precedent references anchor a material description in a real project instead of adjectives."],"srcPage":"Controlling Materiality (1)","tier":"public","img":{"before":"content/examples/material-precedent-concrete/before.jpg","after":"content/examples/material-precedent-concrete/after.jpg"},"modes":["perspective-view"]},{"id":"material-washroom-swap","group":"grender","task":"edit-materials","title":"Public washroom render → material swap by explicit prompt","what":"Changes concrete to white brick, glass to walnut slats and the silver roof to matte black metal on a public washroom render — the RA's demonstration of prompting materials with extreme specificity while everything else stays untouched.","input":"An AI-generated render of a public washroom pavilion","prompt":"Change the materiality of the public washroom while preserving the exact structure, geometry, proportions, composition, camera angle, and surrounding context from the original image. Do not redesign or alter the form in any way. Replace all existing exposed concrete surfaces with smooth white brick featuring subtle mortar joints and a refined matte finish. Change the glass portion that extends upward toward the roof into vertical dark walnut wood slats with a warm rich tone and clean linear spacing, while still maintaining a sense of lightness and transparency. Transform the existing silver roof into a matte painted black metal roof with a clean contemporary appearance. Maintain realistic architectural detailing and material transitions while ensuring the overall image remains cohesive and believable. The sole purpose of this edit is to change the materials; all other aspects of the image must remain untouched.","parts":[{"k":"task","t":"Change the materiality of the public washroom"},{"k":"preserve","t":"exact structure, geometry, proportions, composition, camera angle, and surrounding context; do not redesign or alter the form"},{"k":"change","t":"concrete → smooth white brick with subtle mortar joints and matte finish; upper glass → vertical dark walnut slats with clean linear spacing; silver roof → matte painted black metal"},{"k":"output","t":"the sole purpose of this edit is to change the materials; all other aspects must remain untouched"}],"followups":[],"notes":["RA's rule: never say just “wood” or “glass” — describe exact tone, colour, reflectivity, finish and texture (“warm dark walnut with a matte finish and visible grain texture”)."],"srcPage":"Controlling Materiality (1)","tier":"public","img":{"before":"content/examples/material-washroom-swap/before.jpg","after":"content/examples/material-washroom-swap/after.jpg"},"modes":["perspective-view"]},{"id":"painting-to-orthographic-blueprint","group":"g3d2d","task":"image-to-drawing-set","title":"Building image → plan, elevation and section blueprint","what":"A one-line prompt that extracts a full orthographic blueprint set — plan, elevation and section — from a single pictorial image of a historic villa.","input":"A painterly image of a historic alpine villa","prompt":"Create an orthographic blueprint that describes this building in plan, elevation and section.","parts":[{"k":"task","t":"Create an orthographic blueprint that describes this building in plan, elevation and section"}],"followups":[],"notes":["Deliberately minimal prompt — the drawing conventions carry the specification."],"srcPage":"Photo to Elevation (or CAD)","tier":"public","img":{"before":"content/examples/painting-to-orthographic-blueprint/before.jpg","after":"content/examples/painting-to-orthographic-blueprint/after.jpg"},"modes":["measured-drawing"]},{"id":"pavilion-photo-to-front-side","group":"g3d2d","task":"image-to-elevation","title":"Pavilion photo → front and side views","what":"Generates paired front and side elevations of a timber gridshell pavilion from a single photograph, on a white background.","input":"A photograph of a timber gridshell park pavilion","prompt":"Based on the photo, generate front and side views of the building. White background.","parts":[{"k":"task","t":"Based on the photo, generate front and side views of the building"},{"k":"output","t":"white background"}],"followups":[],"notes":[],"srcPage":"Front and Side View","tier":"public","img":{"before":"content/examples/pavilion-photo-to-front-side/before.jpg","after":"content/examples/pavilion-photo-to-front-side/after.jpg"},"modes":["measured-drawing"]},{"id":"perspective-to-cad-plan","group":"g3d2d","task":"image-to-plan","title":"Perspective render → CAD-style plan drawing","what":"Reads the spatial organization out of a perspective image and reinterprets it as a top-down orthographic plan in clean black-and-white CAD linework.","input":"An aerial perspective render of a timber-clad institutional building with water features and landscape","prompt":"Transform the attached perspective image into a professional architectural plan drawing. Analyze the spatial organization, circulation, landscape elements, building footprints, and design features visible in the perspective, then reinterpret them as a top-down orthographic plan. Maintain the original layout, proportions, relationships between elements, and overall design intent while translating the scene into a clear plan-view representation. Use clean black-and-white linework with consistent CAD-style line weights and simple graphic symbols for trees, planting, paving, and site elements. The final output should read as a coherent architectural or landscape plan that accurately reflects the perspective image while remaining suitable for technical presentation and further editing.","parts":[{"k":"task","t":"Transform the attached perspective image into a professional architectural plan drawing"},{"k":"subject","t":"analyze the spatial organization, circulation, landscape elements, building footprints, and design features visible in the perspective"},{"k":"preserve","t":"maintain the original layout, proportions, relationships between elements, and overall design intent"},{"k":"style","t":"clean black-and-white linework, consistent CAD-style line weights, simple graphic symbols for trees, planting, paving and site elements"}],"followups":[],"notes":[],"srcPage":"Perspective to Plan","tier":"public","img":{"before":"content/examples/perspective-to-cad-plan/before.jpg","after":"content/examples/perspective-to-cad-plan/after.jpg"},"modes":["measured-drawing","perspective-view"]},{"id":"perspective-to-program-masterplan","group":"g3d2d","task":"image-to-diagram","title":"Perspective render → diagrammatic program masterplan","what":"A short follow-up in the same chat turns the perspective into a diagrammatic masterplan with programs, circulation paths, greenspace and the pond indicated graphically.","input":"The same mixed-use pond perspective used for the rendered plan","prompt":"Turn this into a diagrammatic masterplan indicating varied programs (ex. Retail, office, residential), circulation paths, greenspace and the pond.","parts":[{"k":"task","t":"Turn this into a diagrammatic masterplan"},{"k":"change","t":"indicate varied programs (ex. retail, office, residential), circulation paths, greenspace and the pond"}],"followups":[],"notes":["Shows how one input can be cascaded into several drawing types — CAD plan, rendered plan, program diagram — with progressively shorter prompts."],"srcPage":"Perspective to Plan","tier":"public","img":{"before":"content/examples/perspective-to-program-masterplan/before.jpg","after":"content/examples/perspective-to-program-masterplan/after.jpg"},"modes":["diagram","notation-scores","mapping"]},{"id":"perspective-to-rendered-plan","group":"g3d2d","task":"image-to-plan","title":"Perspective render → photorealistic rendered plan","what":"The same perspective-to-plan move but with a photorealistic rendered-plan output: realistic materials, shadows, vegetation and water read from a true top-down viewpoint.","input":"A perspective render of a mixed-use development around a pond","prompt":"Transform that perspective image into a photorealistic architectural plan view. Preserve the spatial organization, circulation patterns, landscape elements, building footprints, and key design features from the original perspective while reinterpreting them from a true top-down viewpoint. Use realistic materials, textures, shadows, vegetation, paving, water features, and site furnishings to create a visually rich rendered plan. Maintain accurate proportions and relationships between all elements so the plan clearly reflects the original design intent. The final image should resemble a professional landscape architecture or urban design rendered plan, combining technical accuracy with photorealistic quality and presentation-level detail.","parts":[{"k":"task","t":"Transform the perspective image into a photorealistic architectural plan view"},{"k":"preserve","t":"spatial organization, circulation patterns, landscape elements, building footprints, and key design features; accurate proportions and relationships"},{"k":"camera","t":"a true top-down viewpoint"},{"k":"style","t":"realistic materials, textures, shadows, vegetation, paving, water features and site furnishings — a professional rendered plan"}],"followups":[],"notes":[],"srcPage":"Perspective to Plan","tier":"public","img":{"before":"content/examples/perspective-to-rendered-plan/before.jpg","after":"content/examples/perspective-to-rendered-plan/after.jpg"},"modes":["perspective-view"]},{"id":"photo-to-3d-model-brick-corner","group":"grender","task":"image-to-3d-model","title":"Street photo → standalone 3D model (brick corner building)","what":"Extracts a real brick corner building from a busy New York street photograph — cars, signage and neighbours removed — into a clean standalone 3D model on white.","input":"A street photograph of a three-storey brick corner building with shopfronts, traffic and signage","prompt":"Convert the attached building photo into a realistic 3D architectural model. Preserve the building's form, proportions, façade details, and materials while removing all background elements and context. Show the building from a 45-degree bird's-eye perspective to emphasize its three-dimensional form and roof geometry. Clearly define materials such as reflective glass, metal, concrete, and brick with realistic lighting and shadows. Place the building on a pure white background, creating the appearance of a professional standalone architectural model.","parts":[{"k":"task","t":"Convert the attached building photo into a realistic 3D architectural model"},{"k":"preserve","t":"preserve the building's form, proportions, façade details, and materials"},{"k":"change","t":"remove all background elements and context; pure white background"},{"k":"camera","t":"45-degree bird's-eye perspective emphasizing form and roof geometry"}],"followups":[],"notes":[],"srcPage":"Photo to 3D Building Model","tier":"public","img":{"before":"content/examples/photo-to-3d-model-brick-corner/before.jpg","after":"content/examples/photo-to-3d-model-brick-corner/after.jpg"},"modes":["model-photography"]},{"id":"photo-to-3d-model-museum","group":"grender","task":"image-to-3d-model","title":"Museum render → standalone 3D model (freeform museum)","what":"Applies the same extraction prompt to a freeform mesh-clad museum image, isolating the architecture from its urban plaza as a clean bird's-eye model on white.","input":"A conceptual render of a freeform museum wrapped in perforated metal mesh, in an urban plaza","prompt":"Convert the attached building photo into a realistic 3D architectural model. Preserve the building's form, proportions, façade details, and materials while removing all background elements and context. Show the building from a 45-degree bird's-eye perspective to emphasize its three-dimensional form and roof geometry. Clearly define materials such as reflective glass, metal, concrete, and brick with realistic lighting and shadows. Place the building on a pure white background, creating the appearance of a professional standalone architectural model.","parts":[{"k":"task","t":"Convert the attached building photo into a realistic 3D architectural model"},{"k":"preserve","t":"preserve the building's form, proportions, façade details, and materials"},{"k":"change","t":"remove all background elements and context; pure white background"},{"k":"camera","t":"45-degree bird's-eye perspective emphasizing form and roof geometry"}],"followups":[],"notes":["The input here is itself an AI generation from the RA's Precedent Exploration exercise — outputs of one stage become inputs of the next."],"srcPage":"Photo to 3D Building Model","tier":"public","img":{"before":"content/examples/photo-to-3d-model-museum/before.jpg","after":"content/examples/photo-to-3d-model-museum/after.jpg"},"modes":["model-photography","perspective-view"]},{"id":"photo-to-3d-model-pavilion","group":"grender","task":"image-to-3d-model","title":"Pavilion photo → standalone 3D model (curved pavilion)","what":"Extracts a curvilinear park pavilion from its rendered context and re-presents it as a clean standalone 3D architectural model on a white background, viewed from a 45-degree bird's-eye angle.","input":"A photorealistic image of a curved concrete pavilion in a park with people and trees","prompt":"Convert the attached building photo into a realistic 3D architectural model. Preserve the building's form, proportions, façade details, and materials while removing all background elements and context. Show the building from a 45-degree bird's-eye perspective to emphasize its three-dimensional form and roof geometry. Clearly define materials such as reflective glass, metal, concrete, and brick with realistic lighting and shadows. Place the building on a pure white background, creating the appearance of a professional standalone architectural model.","parts":[{"k":"task","t":"Convert the attached building photo into a realistic 3D architectural model"},{"k":"preserve","t":"preserve the building's form, proportions, façade details, and materials"},{"k":"change","t":"remove all background elements and context; place the building on a pure white background"},{"k":"camera","t":"show the building from a 45-degree bird's-eye perspective to emphasize its three-dimensional form and roof geometry"},{"k":"style","t":"clearly define materials such as reflective glass, metal, concrete, and brick with realistic lighting and shadows — a professional standalone architectural model"}],"followups":[],"notes":["The RA frames this as a technique for creating assets: the isolated models can feed AI mesh generation, massing studies, diagrammatic analysis, or compositing into new site contexts and masterplans."],"srcPage":"Photo to 3D Building Model","tier":"public","img":{"before":"content/examples/photo-to-3d-model-pavilion/before.jpg","after":"content/examples/photo-to-3d-model-pavilion/after.jpg"},"modes":["model-photography","perspective-view"]},{"id":"photo-to-axon-illustration","group":"g3d2d","task":"image-to-axon","title":"Building photo → clean axonometric illustration","what":"Strips a building photograph of all context and re-draws it as a minimal portfolio-style axonometric illustration on a square plinth with a white background.","input":"A photograph of a building in its urban context","prompt":"Transform the building into a clean architectural axonometric illustration. Remove all background elements, context, vegetation, people, and sky so that only the building remains. Place the building on a simple square plinth to ground the composition. Preserve the overall form, proportions, and key architectural details while simplifying unnecessary visual noise. Use crisp linework, subtle material textures, soft ambient shadows, and a white background to emphasize depth and three-dimensionality. The final image should feel minimal, diagrammatic, and presentation-ready, similar to a professional architectural portfolio graphic.","parts":[{"k":"task","t":"Transform the building into a clean architectural axonometric illustration"},{"k":"change","t":"remove all background elements, context, vegetation, people, and sky; place the building on a simple square plinth"},{"k":"preserve","t":"preserve the overall form, proportions, and key architectural details while simplifying unnecessary visual noise"},{"k":"style","t":"crisp linework, subtle material textures, soft ambient shadows, white background — minimal, diagrammatic, presentation-ready"}],"followups":[],"notes":[],"srcPage":"Photo/Plan to Isometric Diagram","tier":"public","img":{"before":"content/examples/photo-to-axon-illustration/before.jpg","after":"content/examples/photo-to-axon-illustration/after.jpg"},"modes":["projection-systems"]},{"id":"photo-to-desk-model-millboard","group":"grender","task":"image-to-model-photo","title":"Building photo → millboard study model on a desk","what":"Re-presents a building as a handcrafted beige millboard study model photographed in a studio scene, complete with presentation board, Blender screen and model-making tools.","input":"A reference photo of a building","prompt":"Convert the building from the reference photo into a small scale handcrafted architectural model made from beige millboard. Preserve the building's overall form and proportions while expressing it as a clean physical study model with layered cardboard construction and a warm, organic material quality. Place the model on a white cardstock base. Behind it, display a cardboard presentation board featuring a printed image of the original building reference. Beside the model, include a computer monitor showing the building being modeled in Blender, with the 3D workflow clearly visible. Set the scene on a clean studio tabletop with model-making tools, cutting mats, and scale-making materials nearby. Use soft natural lighting, subtle shadows, and a contemporary architectural studio atmosphere to create a realistic model-making workspace.","parts":[{"k":"task","t":"Convert the building from the reference photo into a small scale handcrafted architectural model made from beige millboard"},{"k":"preserve","t":"preserve the building's overall form and proportions"},{"k":"style","t":"clean physical study model with layered cardboard construction and a warm, organic material quality, on a white cardstock base"},{"k":"change","t":"add a cardboard presentation board with the original reference printed on it, a monitor showing the Blender workflow, and model-making tools, cutting mats and materials on a studio tabletop"},{"k":"light","t":"soft natural lighting, subtle shadows, contemporary architectural studio atmosphere"}],"followups":[],"notes":[],"srcPage":"Photo to Model on Desk","tier":"public","img":{"before":"content/examples/photo-to-desk-model-millboard/before.jpg","after":"content/examples/photo-to-desk-model-millboard/after.jpg"},"modes":["model-photography","board-layout"]},{"id":"photo-to-desk-model-pvc","group":"grender","task":"image-to-model-photo","title":"Freeform building → white PVC study model on a desk","what":"Translates a freeform curvilinear building into a smooth white PVC physical study model in the same staged studio scene, preserving the flowing geometry and sculptural form.","input":"A render of a freeform curvilinear pavilion","prompt":"Convert the freeform building from the reference image into a small-scale architectural model made from smooth white PVC. Preserve the flowing geometry, curves, and sculptural form while expressing it as a clean physical study model with crisp edges and a refined matte-to-satin finish. Place the model on a white cardstock base. Behind it, display a presentation board featuring a printed image of the original building reference. Beside the model, include a computer monitor showing the building being modeled in Blender, with the 3D workflow and form development clearly visible. Set the scene on a clean studio tabletop with model-making tools, cutting mats, and architectural design materials nearby. Use soft natural lighting, subtle shadows, and a contemporary architectural studio atmosphere to create a realistic model-making workspace.","parts":[{"k":"task","t":"Convert the freeform building from the reference image into a small-scale architectural model made from smooth white PVC"},{"k":"preserve","t":"preserve the flowing geometry, curves, and sculptural form"},{"k":"style","t":"clean physical study model with crisp edges and a refined matte-to-satin finish, on a white cardstock base"},{"k":"change","t":"presentation board with the original reference, monitor showing the Blender form development, studio tabletop with tools and cutting mats"},{"k":"light","t":"soft natural lighting, subtle shadows, contemporary studio atmosphere"}],"followups":[],"notes":["The material spec is matched to the geometry — millboard for the orthogonal building, smooth PVC for the freeform one."],"srcPage":"Photo to Model on Desk","tier":"public","img":{"before":"content/examples/photo-to-desk-model-pvc/before.jpg","after":"content/examples/photo-to-desk-model-pvc/after.jpg"},"modes":["model-photography"]},{"id":"plan-to-interior-render","group":"g2d3d","task":"plan-to-perspective","title":"Floor plan → interior render (view from the red arrow)","what":"Turns an annotated floor plan directly into a photorealistic interior view taken from the direction of a red arrow drawn on the plan, translating black wall poché accurately into 3D space.","input":"A residential floor plan with black wall poché and a red arrow marking the camera direction","prompt":"Transform the attached floor plan into a photorealistic interior rendering viewed from the direction of the red arrow. The black elements in the plan represent walls and must be translated accurately into the 3D space. Maintain the exact room layout, wall locations, window placements, door openings, circulation paths, and spatial proportions shown in the plan. Do not alter or invent any architectural elements. Furnish the interior in a Mid-Century Modern style using warm tones, dark walnut wood, leather seating, and clean modern furnishings. Use realistic materials, natural daylight, and soft shadows to create a warm, inviting atmosphere while remaining faithful to the floor plan.","parts":[{"k":"task","t":"Transform the attached floor plan into a photorealistic interior rendering viewed from the direction of the red arrow"},{"k":"subject","t":"the black elements in the plan represent walls and must be translated accurately into the 3D space"},{"k":"preserve","t":"maintain the exact room layout, wall locations, window placements, door openings, circulation paths, and spatial proportions shown in the plan"},{"k":"negative","t":"do not alter or invent any architectural elements"},{"k":"style","t":"furnish in a Mid-Century Modern style using warm tones, dark walnut wood, leather seating, and clean modern furnishings"},{"k":"light","t":"realistic materials, natural daylight, and soft shadows for a warm, inviting atmosphere"}],"followups":[],"notes":["The RA marks the intended camera position directly on the plan (red arrow) so the model does not have to guess a viewpoint."],"srcPage":"Plan to Bird's-Eye & Perspective","tier":"public","img":{"before":"content/examples/plan-to-interior-render/before.jpg","after":"content/examples/plan-to-interior-render/after.jpg"},"modes":["measured-drawing","perspective-view"]},{"id":"plan-to-townhouse-birdseye","group":"g2d3d","task":"plan-to-perspective","title":"Landscape plan → bird's-eye render (townhouse complex)","what":"Lifts a landscape plan into a photorealistic 3D bird's-eye rendering of a townhouse complex, then walks the camera down to eye level with two short follow-up prompts.","input":"A landscape plan of a townhouse development showing building footprints, circulation and planting","prompt":"Transform the attached landscape plan into a photorealistic 3D bird's-eye architectural rendering. Convert all buildings into contemporary townhouse forms with dark grey slate-tiled roofs while following the plan layout, building footprints, circulation, and landscape design accurately. Surround the site with detailed urban context including paved roads, sidewalks, street trees, planting, parked cars, and neighboring buildings. Apply realistic materials and textures throughout, with detailed vegetation and site furnishings. Render in natural daylight with soft shadows and a professional architectural visualization quality. Preserve the overall site organization and proportions from the input plan.","parts":[{"k":"task","t":"Transform the attached landscape plan into a photorealistic 3D bird's-eye architectural rendering"},{"k":"change","t":"convert all buildings into contemporary townhouse forms with dark grey slate-tiled roofs; surround the site with paved roads, sidewalks, street trees, planting, parked cars, and neighboring buildings"},{"k":"preserve","t":"follow the plan layout, building footprints, circulation, and landscape design accurately; preserve the overall site organization and proportions"},{"k":"style","t":"realistic materials and textures, detailed vegetation and site furnishings, professional architectural visualization quality"},{"k":"light","t":"natural daylight with soft shadows"}],"followups":["Lower the camera, looking toward the building, with the landscape design area in the foreground","Create a eye level perspective view from the driveway of one of the homes, looking towards the front of the home."],"notes":["The camera is stepped down in stages — bird's-eye first, then lowered, then true eye level — rather than asking for the final view in one jump."],"srcPage":"Plan to Bird's-Eye & Perspective","tier":"public","img":{"before":"content/examples/plan-to-townhouse-birdseye/before.jpg","after":"content/examples/plan-to-townhouse-birdseye/after.jpg","steps":["content/examples/plan-to-townhouse-birdseye/step1.jpg","content/examples/plan-to-townhouse-birdseye/step2.jpg"]},"modes":["perspective-view"]},{"id":"render-to-analysis-diagrams","group":"g3d2d","task":"image-to-diagram","title":"Library render → circulation, exploded and analysis diagrams","what":"Produces a coordinated diagram series — circulation, exploded isometric by floor, accessibility, and view analysis — from the same library design reference.","input":"The RA's final night render of the library project","prompt":"Using the attached library design as reference, generate a series of professional architectural diagrams including circulation, exploded isometric, accessibility, and view analysis diagrams. The exploded isometric should separate the building by floor levels while maintaining accurate structural and spatial relationships. The circulation diagram should clearly illustrate primary and secondary movement paths throughout the building. The accessibility diagram should communicate accessible routes, entrances, vertical circulation, and inclusive design features. The view diagram should highlight key sightlines and visual connections to the surrounding context. All diagrams should be presented in a traditional technical architectural style using clean black and white linework, minimal shading, consistent graphic hierarchy, and clear diagrammatic clarity similar to professional architectural presentation boards.","parts":[{"k":"task","t":"Generate a series of professional architectural diagrams: circulation, exploded isometric, accessibility, and view analysis"},{"k":"change","t":"exploded isometric separated by floor levels; circulation showing primary and secondary paths; accessibility routes and entrances; sightline/view analysis"},{"k":"preserve","t":"maintain accurate structural and spatial relationships to the referenced design"},{"k":"style","t":"traditional technical style — clean black and white linework, minimal shading, consistent graphic hierarchy"}],"followups":[],"notes":[],"srcPage":"Technical Drawing (3D to 2D)","tier":"public","img":{"before":"content/examples/render-to-analysis-diagrams/before.jpg","after":"content/examples/render-to-analysis-diagrams/after.jpg"},"modes":["projection-systems","diagram","notation-scores"]},{"id":"render-to-axon-illustration","group":"g3d2d","task":"image-to-axon","title":"Night render → clean axonometric illustration (glass-brick offices)","what":"The same axonometric-extraction prompt applied to a night render of a stacked glass-brick office building, producing a second portfolio-style axon on a plinth.","input":"A night render of a modular stacked office building with a glowing glass-brick facade","prompt":"Transform the building into a clean architectural axonometric illustration. Remove all background elements, context, vegetation, people, and sky so that only the building remains. Place the building on a simple square plinth to ground the composition. Preserve the overall form, proportions, and key architectural details while simplifying unnecessary visual noise. Use crisp linework, subtle material textures, soft ambient shadows, and a white background to emphasize depth and three-dimensionality. The final image should feel minimal, diagrammatic, and presentation-ready, similar to a professional architectural portfolio graphic.","parts":[{"k":"task","t":"Transform the building into a clean architectural axonometric illustration"},{"k":"change","t":"remove all background, context, vegetation, people and sky; square plinth to ground the composition"},{"k":"preserve","t":"overall form, proportions, and key architectural details"},{"k":"style","t":"crisp linework, subtle textures, soft ambient shadows, white background"}],"followups":[],"notes":["The input is the RA's own Precedent Exploration output (Habitat 67 × glass brick), reused here as source material."],"srcPage":"Photo/Plan to Isometric Diagram","tier":"public","img":{"before":"content/examples/render-to-axon-illustration/before.jpg","after":"content/examples/render-to-axon-illustration/after.jpg"},"modes":["projection-systems","perspective-view"]},{"id":"render-to-drawing-set","group":"g3d2d","task":"image-to-drawing-set","title":"Library renders → full technical drawing set","what":"Generates a complete architectural drawing set — plans, sections, elevations and a perforated-panel detail — interpreted from the RA's iteratively developed library renders.","input":"Two renders of the RA's library project (day render and final night render)","prompt":"Based on the attached library renders, generate a complete set of professional architectural technical drawings including floor plans, building sections, exterior elevations, and detailed drawings of the perforated façade panels. The drawings should accurately interpret the geometry, structure, circulation, façade system, and material logic of the design shown in the render. Present everything in a clean black and white architectural drafting style with precise line hierarchy, annotations, poche, and technical detailing consistent with professional construction drawing standards. The perforated panel detail should clearly show panel assembly, attachment logic, material layering, and perforation pattern at an architectural detail scale. Maintain consistency across all drawings so they read as one cohesive architectural drawing set.","parts":[{"k":"task","t":"Generate a complete set of professional architectural technical drawings: floor plans, building sections, exterior elevations, and perforated façade panel details"},{"k":"preserve","t":"accurately interpret the geometry, structure, circulation, façade system, and material logic of the design shown in the render"},{"k":"style","t":"clean black and white drafting style with precise line hierarchy, annotations, poché, and technical detailing to construction-drawing standards"},{"k":"output","t":"maintain consistency so all drawings read as one cohesive set"}],"followups":[],"notes":["From the Technical Drawing (3D to 2D) method page — the library project developed under Iterative Prompting is carried into the drawing stage."],"srcPage":"Technical Drawing (3D to 2D)","tier":"public","img":{"before":"content/examples/render-to-drawing-set/before.jpg","after":"content/examples/render-to-drawing-set/after.jpg"},"modes":["measured-drawing"]},{"id":"render-to-elevation-svg","group":"g3d2d","task":"image-to-elevation","title":"Bath house render → CAD-style elevation (+ SVG step)","what":"Flattens an aerial render of the bath house project into a precise black-and-white orthographic elevation, then pushes the result through ChatGPT into an editable SVG/CAD file.","input":"An aerial render of a timber bath house building","prompt":"Create a clean, professional architectural elevation drawing of the building. Render the elevation in precise black-and-white linework on a pure white background, showing accurate proportions, façade composition, window and door locations, material joints, and architectural detailing. Use a technical drafting style similar to a CAD-generated elevation, with consistent line weights and crisp edges. Do not use perspective, shadows, or three-dimensional effects—the drawing should remain a flat orthographic elevation suitable for architectural presentation boards. Remove all surrounding context, text, dimensions, and annotations, focusing solely on the building elevation.","parts":[{"k":"task","t":"Create a clean, professional architectural elevation drawing of the building"},{"k":"style","t":"precise black-and-white linework on a pure white background, technical drafting style similar to a CAD-generated elevation, consistent line weights and crisp edges"},{"k":"preserve","t":"accurate proportions, façade composition, window and door locations, material joints, and architectural detailing"},{"k":"negative","t":"no perspective, shadows, or three-dimensional effects; remove all surrounding context, text, dimensions, and annotations"}],"followups":["Turn this plan to single SVG version of the CAD drawing, keeping the vectorized, clean line style."],"notes":["RA note: you can ask ChatGPT to generate an SVG or DWG file and open it in AutoCAD or Illustrator — but this remains imprecise, so manual editing is required."],"srcPage":"Photo to Elevation (or CAD)","tier":"public","img":{"before":"content/examples/render-to-elevation-svg/before.jpg","after":"content/examples/render-to-elevation-svg/after.jpg","steps":["content/examples/render-to-elevation-svg/step1.jpg"]},"modes":["measured-drawing","perspective-view"]},{"id":"render-to-figure-ground","group":"g3d2d","task":"image-to-diagram","title":"Render → figure-ground diagram","what":"Abstracts an aerial image into the classic black-and-white figure-ground, showing built mass against open space. The starting point of almost every urban analysis.","input":"An aerial render or drone photo of an urban block and its immediate surroundings, taken near vertical","prompt":"Extract a figure-ground diagram from this aerial image: building footprints as solid black shapes, everything else pure white. Keep every footprint shape, the gaps between buildings and the courtyard voids exactly as they appear. Drop all colour, texture, shadow, vegetation, roads and vehicles. Flat graphic diagram in the tradition of a Nolli-derived figure-ground, hard edges, no outlines. True top-down orthographic view. One flat black-and-white diagram, no text, no north arrow, no scale bar.","parts":[{"k":"task","t":"Extract a figure-ground diagram from this aerial image: building footprints as solid black shapes, everything else pure white"},{"k":"preserve","t":"keep every footprint shape, the gaps between buildings and the courtyard voids exactly as they appear"},{"k":"change","t":"drop all colour, texture, shadow, vegetation, roads and vehicles"},{"k":"style","t":"flat graphic diagram, Nolli tradition, hard edges, no outlines around the black shapes"},{"k":"camera","t":"true top-down orthographic view, no oblique angle"},{"k":"output","t":"one flat black-and-white diagram, no text, no north arrow, no scale bar"}],"followups":["Invert it: open space black, buildings white; geometry identical","Add the primary streets back as thin grey lines; footprints untouched","Fill only the buildings inside the central block in red; all others stay black"],"notes":["Cast shadows get merged into footprints, fattening buildings toward the sun side — compare edges on the shadow side","Tree canopies become black blobs counted as built mass; check anything round and fuzzy","The model often adds a helpful grey road layer you did not ask for; forbid intermediate tones"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["diagram","perspective-view"]},{"id":"render-to-watercolour","group":"grender","task":"restyle-hand-media","title":"Render → watercolour","what":"Repaints a finished render as a loose architectural watercolour, trading photoreal certainty for atmosphere. Good for concept-stage presentations where a render would overpromise.","input":"A photorealistic exterior render of a low pavilion in a park, daylight, fixed camera","prompt":"Repaint this render as a loose architectural watercolour of exactly the same scene. Keep the composition, camera, building geometry and shadow direction identical. Transparent layered washes, a wet-on-wet sky, granulating pigment in the greens, white paper reserved for the brightest highlights, and a few faint pencil construction lines left visible under the paint. Same daylight as the render, translated into warm and cool wash temperature. One image with a cold-press paper texture and a ragged unpainted border, no signature, no text.","parts":[{"k":"task","t":"Repaint this render as a loose architectural watercolour of exactly the same scene"},{"k":"preserve","t":"composition, camera, building geometry and shadow direction identical; every building edge stays where it is"},{"k":"style","t":"transparent layered washes, wet-on-wet sky, granulating pigment, reserved white paper highlights, faint pencil construction lines"},{"k":"light","t":"same daylight, translated into warm and cool wash temperature rather than rendered shading"},{"k":"output","t":"cold-press paper texture, ragged unpainted border, no signature, no text"}],"followups":["Loosen the vegetation further into wet blooms, but keep the building edges crisp","Reduce the palette to ultramarine, burnt sienna and yellow ochre; composition unchanged","Same painting at dusk: warm windows, cool violet shadows, geometry frozen"],"notes":["Edges melt: the building geometry drifts under the brushwork — overlay the result on the render to check","Results often look like a digital filter, evenly textured everywhere; asking for reserved white paper and visible pencil fights this","Watercolour prompts tend to oversaturate; name a limited pigment palette to keep it honest"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["sketch","perspective-view"]},{"id":"renders-to-library-board","group":"gboards","task":"images-to-board","title":"Project renders → competition board (library)","what":"Composes the RA's accumulated library assets — renders, diagrams, masterplan and technical drawings — into one competition-style board with a bold generated project title.","input":"Two renders of the library project plus its diagrams, master plan and technical drawings","prompt":"Create a single architectural presentation board image using the attached renders, diagrams, master plan, and technical drawings. Include a bold project title at the top, giving the library a compelling name in large black font. Arrange the content with a clean visual hierarchy, generous white margins, and a minimalist layout inspired by professional architecture competition boards. Prioritize the final renders while supporting them with smaller massing diagrams and linework drawings. The output should be one high-resolution board image, not a slideshow or multi-page presentation.","parts":[{"k":"task","t":"Create a single presentation board image using the attached renders, diagrams, master plan and technical drawings"},{"k":"change","t":"add a bold project title at the top — give the library a compelling name in large black font"},{"k":"style","t":"clean visual hierarchy, generous white margins, minimalist competition-board layout; renders prioritized, diagrams supporting"},{"k":"output","t":"one high-resolution board image, not a slideshow or multi-page presentation"}],"followups":[],"notes":["The end point of the library workflow that runs through the Iterative Prompting and Technical Drawing pages."],"srcPage":"Rendering to Presentation Board","tier":"public","img":{"before":"content/examples/renders-to-library-board/before.jpg","after":"content/examples/renders-to-library-board/after.jpg"},"modes":["board-layout","diagram","measured-drawing"]},{"id":"section-to-3d-isometric","group":"g2d3d","task":"section-to-view","title":"Landscape section → realistic 3D isometric","what":"Converts a flat landscape section drawing into a photorealistic 3D isometric rendering with terrain, planting, retaining walls and paving — explicitly avoiding diagrammatic linework.","input":"A drafted landscape section drawing with elevation changes, planting and retaining structures","prompt":"Convert that landscape section drawing into a realistic 3D isometric rendering. Maintain the original spatial layout, elevation changes, and design elements while translating them into a fully three-dimensional representation. Include terrain, planting, paving, seating areas, retaining walls, and structural elements with realistic materials and textures. Use detailed vegetation, natural grass, shrubs, and trees to create a lifelike landscape appearance. Avoid outlines, graphic edges, or diagrammatic linework—instead rely on realistic lighting, shadows, material definition, and depth to communicate form. The final image should feel like a professional landscape visualization viewed in an isometric perspective, balancing clarity with photorealistic quality for presentation and portfolio use.","parts":[{"k":"task","t":"Convert the landscape section drawing into a realistic 3D isometric rendering"},{"k":"preserve","t":"maintain the original spatial layout, elevation changes, and design elements"},{"k":"change","t":"include terrain, planting, paving, seating areas, retaining walls, and structural elements with realistic materials and textures"},{"k":"negative","t":"avoid outlines, graphic edges, or diagrammatic linework"},{"k":"style","t":"realistic lighting, shadows, material definition and depth — a professional landscape visualization in isometric perspective"}],"followups":[],"notes":[],"srcPage":"Section to 3D","tier":"public","img":{"before":"content/examples/section-to-3d-isometric/before.jpg","after":"content/examples/section-to-3d-isometric/after.jpg"},"modes":["projection-systems","diagram","measured-drawing"]},{"id":"section-to-section-perspective","group":"g2d3d","task":"section-to-view","title":"Flat section → collage-style section perspective","what":"Adds depth behind a flat architectural section: cut earth rendered as black stipple poché, and the landscape beyond treated as a Photoshop-style collage with layered textures and cutout vegetation.","input":"A flat architectural/landscape section drawing","prompt":"Transform the attached flat architectural section into a section perspective. Preserve the original cut line, building geometry, and spatial relationships, but introduce depth and perspective to reveal more of the landscape beyond the section cut. Render all cut ground and earth elements with a dense black stipple poche to clearly distinguish the sectioned terrain. Beyond the cut line, depict the landscape, vegetation, pathways, structures, and site elements as a Photoshop-style architectural collage using layered textures, cutout vegetation, atmospheric shading, and mixed-media rendering techniques. Maintain accurate proportions while using perspective, texture overlays, and subtle shadows to create depth and visual richness. The final image should have an artistic landscape architecture presentation aesthetic, combining technical section drawing with expressive collage rendering.","parts":[{"k":"task","t":"Transform the attached flat architectural section into a section perspective"},{"k":"preserve","t":"preserve the original cut line, building geometry, and spatial relationships; maintain accurate proportions"},{"k":"change","t":"introduce depth and perspective to reveal the landscape beyond the cut; render cut ground with dense black stipple poché"},{"k":"style","t":"Photoshop-style architectural collage beyond the cut — layered textures, cutout vegetation, atmospheric shading, mixed-media rendering"}],"followups":[],"notes":[],"srcPage":"Section to 3D","tier":"public","img":{"before":"content/examples/section-to-section-perspective/before.jpg","after":"content/examples/section-to-section-perspective/after.jpg"},"modes":["section-perspective","hybrid-drawing","perspective-view"]},{"id":"sketch-to-massing-study","group":"g2d3d","task":"sketch-to-massing","title":"Loose sketch → massing study","what":"Cleans a rough concept sketch into a disciplined massing image without redesigning it. Good for taking a napkin idea into a review without pretending it is further along than it is.","input":"A loose perspective pen sketch of two intersecting bar buildings, scanned from a sketchbook, wobbly lines and construction marks","prompt":"Interpret this loose sketch as a clean massing study of the same design. Keep the relationship between the two bars exactly as sketched: their crossing angle, the point of overlap and their relative heights and lengths. Resolve the wobbly linework into crisp rectilinear volumes; strip all detail, openings and texture. Matte white study volumes on a plain mid-grey groundplane, like a foam model photographed in a studio. Three-quarter aerial view matching the viewpoint of the sketch. Single soft studio light from the upper left. One image, empty background, no context buildings, no entourage.","parts":[{"k":"task","t":"Interpret this loose sketch as a clean massing study of the same design"},{"k":"preserve","t":"keep the relationship between the two bars exactly as sketched: crossing angle, point of overlap, relative heights and lengths"},{"k":"change","t":"resolve the wobbly linework into crisp rectilinear volumes; strip all detail, openings and texture"},{"k":"style","t":"matte white study volumes on a plain mid-grey groundplane, like a photographed foam model"},{"k":"camera","t":"three-quarter aerial view matching the viewpoint of the sketch"},{"k":"light","t":"single soft studio light from the upper left, gentle contact shadows"}],"followups":["Raise the shorter bar by one increment so the two volumes read as distinct heights; keep the crossing angle fixed","Show the same massing from directly above as a top view; volumes unchanged","Chamfer the corner where the bars meet; everything else stays frozen"],"notes":["The model resolves ambiguity by adding a third volume or a podium that was never sketched — count the parts","Sketch charm becomes fake precision: the crossing angle gets rationalised to 90 degrees, check it","Construction lines in the scan can be read as extra walls; crop or clean the scan first"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["sketch"]},{"id":"spreadsheet-to-tree-masterplan","group":"g3d2d","task":"data-to-diagram","title":"Species spreadsheet → tree-placement masterplan diagrams","what":"Feeds an Excel table of tree species and quantities (plus a site aerial) into the model to generate black-and-white masterplan diagrams testing tree-placement strategies for heat-island mitigation at the UBC Alumni Centre.","input":"An Excel spreadsheet of wanted species and amounts, with an aerial image of the site","prompt":"Create a series of black and white landscape master plan diagrams showing different tree placement strategies around the UBC Alumni Centre based on the provided tree species table. Utilize the specified quantities of Douglas Fir, Western Redcedar, Western Hemlock, and Sitka Spruce to generate multiple iterations exploring how tree placement can improve urban heat island conditions, provide shade coverage, reduce ground temperature, and enhance pedestrian comfort. The base site plan should be represented entirely in clean black and white architectural linework, including building footprints, pathways, surrounding context, circulation routes, and landscape edges. The trees should stand out from the monochromatic drawing through subtle colour coding by species, allowing each tree type to be clearly distinguished while maintaining an overall diagrammatic presentation style. Tree canopies should be represented in plan using simplified graphic symbols and canopy extents. The diagrams should investigate varying densities, clustering strategies, canopy distributions, and spatial relationships between trees, pathways, gathering areas, and the surrounding urban context. Consider how larger canopy trees can create shaded zones and cooling corridors, while smaller or clustered species can define spatial edges, transition spaces, and ecological layering. Some iterations can emphasize dense shaded gathering spaces, while others may focus on circulation corridors, open plazas, or microclimate optimization. Represent the proposals as conceptual landscape architecture master plans rather than photorealistic renders. Maintain a clean presentation-quality aesthetic similar to professional urban design and landscape architecture diagrams, with minimal graphics, clear hierarchy, and strong readability.","parts":[{"k":"task","t":"Create a series of black and white landscape master plan diagrams showing different tree placement strategies based on the provided tree species table"},{"k":"subject","t":"use the specified quantities of Douglas Fir, Western Redcedar, Western Hemlock, and Sitka Spruce to explore heat-island mitigation, shade coverage, ground temperature and pedestrian comfort"},{"k":"style","t":"base plan in clean black and white linework; trees colour-coded by species with canopy-extent symbols"},{"k":"change","t":"iterations varying density, clustering, canopy distribution — shaded gathering spaces, cooling corridors, plazas, microclimate optimization"},{"k":"negative","t":"conceptual master plans rather than photorealistic renders"}],"followups":[],"notes":["Appears on both the Reference Inputs and Technical Drawing pages — numerical data (a spreadsheet) is itself a usable AI input."],"srcPage":"Technical Drawing (3D to 2D)","tier":"public","img":{"before":"content/examples/spreadsheet-to-tree-masterplan/before.jpg","after":"content/examples/spreadsheet-to-tree-masterplan/after.jpg"},"modes":["diagram","mapping"]},{"id":"streetview-redesign","group":"grender","task":"edit-canvas","title":"Street view → streetscape proposal","what":"Redesigns the public realm inside a real street photo while the buildings stay as witnesses. The most persuasive image type for community consultation.","input":"A street-level photo of an existing road: wide asphalt, parked cars both sides, narrow cracked sidewalks, no trees","prompt":"Redesign the streetscape in this photo as a proposal image. The building facades on both sides, the sky and the camera position stay exactly as photographed; only the ground plane and street furniture zone change. Narrow the carriageway to two lanes, widen both sidewalks with light concrete pavers, add a continuous row of honey locust street trees in permeable tree pits at 8 m spacing, a protected cycle lane on the right side, and simple dark-grey bollards and benches. Keep the existing daylight and shadow direction, with new tree shadows falling consistently. One photorealistic image, same crop as the source photo. Do not renovate, clean or recolour the building facades; no new buildings; keep some ordinary parked cars so the street stays believable.","parts":[{"k":"task","t":"Redesign the streetscape in this photo as a proposal image"},{"k":"preserve","t":"building facades, sky, camera position and lens exactly as photographed; only the ground plane and street furniture zone change"},{"k":"change","t":"two-lane carriageway, widened paver sidewalks, honey locust street trees in permeable pits at 8 m spacing, protected cycle lane, dark-grey bollards and benches"},{"k":"light","t":"existing daylight and shadow direction kept, new tree shadows falling consistently"},{"k":"negative","t":"do not renovate, clean or recolour the facades; no new buildings; keep some ordinary parked cars"}],"followups":["Same proposal in winter with leafless trees, to show the honest worst case","Remove the cycle lane and widen the planted verge instead; everything else stays","Populate lightly: six pedestrians and one cyclist at true scale; design unchanged"],"notes":["Facades get freshly painted and re-glazed uninvited, which reads as dishonest in consultation — lock them explicitly","New kerb lines ignore the photo's perspective and bend at the vanishing point; check convergence against the originals","Street trees come out at ten years' growth with perfect lollipop crowns; specify age and spacing"],"srcPage":"Platform-authored (v1)","tier":"public","authored":true,"img":null,"modes":["perspective-view"]},{"id":"style-linework-to-illustration","group":"grender","task":"restyle-collage","title":"Linework isometric → flat colour illustration (palette input)","what":"Colours a student's isometric linework drawing like a colouring book: linework converted to crisp white lines with flat fills taken from an attached colour palette, in the manner of a J.C. Architecture editorial illustration.","input":"A student linework isometric drawing, plus a style reference (J.C. Architecture) and a colour palette image","prompt":"Transform the input isometric linework drawing into a stylized architectural illustration inspired by the attached reference image. Maintain the exact isometric perspective, geometry, composition, and architectural layout from the original drawing while converting the presentation style into a clean graphic illustration. The process should function similarly to colouring within the existing linework rather than redesigning or reinterpreting the drawing. Do not add, remove, or alter any architectural elements, furniture, objects, decorations, vegetation, or contextual components. Preserve all original linework exactly as provided. Convert the existing linework to crisp white lines and apply solid flat colour fills beneath the linework using the attached colour palette. Use minimal gradients or shading so the illustration remains graphic, clean, and diagrammatic. The people within the scene do not need to strictly follow the attached colour palette and can use more natural or varied colours to help the image feel lively while remaining visually cohesive. Avoid photorealism, textures, painterly effects, sketchiness, or additional detailing. The final output should feel like a polished architectural editorial illustration with strong clarity, controlled colour blocking, and the appearance of a carefully coloured architectural drawing.","parts":[{"k":"task","t":"Transform the isometric linework drawing into a stylized illustration inspired by the attached reference — like colouring within the existing linework"},{"k":"preserve","t":"exact isometric perspective, geometry, composition and layout; preserve all original linework exactly; do not add, remove or alter any elements"},{"k":"change","t":"convert linework to crisp white lines; apply solid flat colour fills beneath, using the attached colour palette (people may use more natural colours)"},{"k":"negative","t":"avoid photorealism, textures, painterly effects, sketchiness, or additional detailing; minimal gradients"}],"followups":[],"notes":[],"srcPage":"Changing Render Styles (1)","tier":"public","img":{"before":"content/examples/style-linework-to-illustration/before.jpg","after":"content/examples/style-linework-to-illustration/after.jpg"},"modes":["projection-systems","measured-drawing"]},{"id":"style-photoreal-to-collage","group":"grender","task":"restyle-collage","title":"Photorealistic render → Photoshop collage style","what":"Reinterprets a photorealistic cafe render as a handcrafted mixed-media collage visualization, guided by an attached student collage render (Katie Phillips, 2021) as the style reference.","input":"A Gemini photorealistic render of the cafe project, plus a collage-style reference render","prompt":"Transform the input photorealistic render into an artistic Photoshop collage-style architectural visualization inspired by the attached reference image. The final image should feel handcrafted and atmospheric rather than digitally perfect. Use layered textures, cutout materials, paper-like overlays, painterly shadows, grain, sketch-like edges, and mixed-media elements to create a collage aesthetic. Incorporate expressive vegetation, textured skies, and slightly abstract human figures similar to architectural presentation collages. Maintain the exact composition, perspective, geometry, and overall architectural form of the original render. Do not change the building design or layout — only reinterpret the image through a warm, serene, mixed-media collage style with strong texture variation and an artistic presentation quality.","parts":[{"k":"task","t":"Transform the input photorealistic render into an artistic Photoshop collage-style visualization inspired by the attached reference"},{"k":"style","t":"layered textures, cutout materials, paper-like overlays, painterly shadows, grain, sketch-like edges, mixed-media elements; expressive vegetation, textured skies, slightly abstract figures"},{"k":"preserve","t":"maintain the exact composition, perspective, geometry, and overall architectural form"},{"k":"negative","t":"do not change the building design or layout — only reinterpret the style"}],"followups":[],"notes":[],"srcPage":"Changing Render Styles (1)","tier":"public","img":{"before":"content/examples/style-photoreal-to-collage/before.jpg","after":"content/examples/style-photoreal-to-collage/after.jpg"},"modes":["hybrid-drawing","perspective-view"]},{"id":"style-photoreal-to-red-linework","group":"grender","task":"restyle-hand-media","title":"Photorealistic render → red pen/linework illustration","what":"Converts a photorealistic render into a refined CAD-style pen illustration — deep red linework for the architecture against lighter grey context — modelled on a Morris + Company reference drawing.","input":"A Gemini photorealistic render, plus a Morris + Company linework render as style reference","prompt":"Transform the input photorealistic render into a refined architectural CAD-style pen and linework illustration inspired by the attached Morris+Company reference render. The overall drawing style should feel clean, precise, and hand-drafted, resembling a high-quality architectural CAD block or conceptual line drawing rather than a heavily sketched illustration. Use light, elegant, and controlled linework with minimal visual heaviness. Avoid thick outlines, dense shadows, or overly dark sketch effects. The primary theme colour should be deep red, with the building and architectural elements rendered predominantly in fine red linework on a pure white background. Preserve the exact composition, perspective, geometry, and architectural design from the original render. Texture and materiality should be communicated subtly through delicate line-based techniques such as fine hatching, stippling, crosshatching, and patterned fills while remaining consistent with the clean CAD-like aesthetic. The surrounding context, vegetation, people, and ground plane should remain simplified and graphic, using lighter black and grey linework to create contrast with the red architecture. Depth and hierarchy should be achieved through variation in line density, spacing, and opacity rather than heavy shading. The final image should feel atmospheric, minimal, refined, and presentation-quality — combining the clarity of CAD drawings with the artistry of architectural linework illustration.","parts":[{"k":"task","t":"Transform the photorealistic render into a refined CAD-style pen and linework illustration inspired by the Morris+Company reference"},{"k":"style","t":"deep red fine linework for the architecture on pure white; hatching, stippling, crosshatching and patterned fills for texture; context in lighter black/grey linework"},{"k":"preserve","t":"exact composition, perspective, geometry, and architectural design"},{"k":"negative","t":"avoid thick outlines, dense shadows, or overly dark sketch effects; depth through line density rather than heavy shading"}],"followups":[],"notes":[],"srcPage":"Changing Render Styles (1)","tier":"public","img":{"before":"content/examples/style-photoreal-to-red-linework/before.jpg","after":"content/examples/style-photoreal-to-red-linework/after.jpg"},"modes":["measured-drawing","perspective-view"]},{"id":"timeline-high-line","group":"gboards","task":"text-to-timeline","title":"Text → plan-view timeline (the High Line)","what":"Five plan-view diagrams of the same stretch of the High Line, 1930s rail corridor to present-day park, arranged as one poster-ready landscape-evolution infographic in a muted vector palette.","input":"","prompt":"Create a horizontal plan-view timeline infographic illustrating the transformation of the High Line from abandoned railway infrastructure to a world-renowned urban landscape. Composition: Design the timeline as a sequence of five plan-view diagrams arranged from left to right across a clean white background. Each stage should show the same portion of the High Line from a bird's-eye perspective to clearly illustrate change over time. Connect each plan with arrows and a continuous timeline graphic. Timeline Stages: 1930s Active Rail Corridor – Freight railway tracks serving Manhattan's industrial district. 1980s Abandonment – Disused infrastructure with spontaneous vegetation emerging between tracks. 1999 Preservation Movement – Community advocacy and early visions for adaptive reuse. 2006–2014 Landscape Transformation – Phased implementation of pathways, planting systems, seating, and public spaces. Present-Day High Line – Mature landscape featuring diverse vegetation, gathering spaces, art installations, and pedestrian circulation. Graphic Style: Use simplified landscape architecture diagrams rather than realistic imagery. Illustrate tracks, pathways, planting zones, buildings, and circulation using clean vector graphics. Maintain a consistent drawing style across all five plans. Colour Palette: White background with a cohesive palette of muted greens, sage, charcoal gray, warm beige, and soft terracotta. Show ecological growth and increasing landscape complexity through gradual colour changes. Use a single accent colour for dates, arrows, and key annotations. Details & Annotation: Include concise labels, dates, and callouts describing major changes at each stage. Add small diagrammatic icons showing ecology, public space, and adaptive reuse. Use minimal text and rely primarily on graphics to tell the story. Presentation Quality: Clean poster-ready layout suitable for a landscape architecture portfolio or presentation board. Strong visual hierarchy, generous white space, and professional typography. The final graphic should read as a cohesive landscape evolution diagram rather than five separate images.","parts":[{"k":"task","t":"Create a horizontal plan-view timeline infographic of the High Line's transformation"},{"k":"subject","t":"five stages, 1930s rail corridor to present-day park, each showing the same portion of the site from above"},{"k":"style","t":"simplified vector landscape diagrams, consistent drawing style; muted greens, sage, charcoal, beige, terracotta; one accent colour"},{"k":"output","t":"poster-ready, cohesive — must read as one landscape evolution diagram rather than five separate images"}],"followups":[],"notes":[],"srcPage":"Timeline Site Analysis","tier":"public","img":{"after":"content/examples/timeline-high-line/after.jpg"},"modes":["board-layout","diagram","notation-scores"]},{"id":"timeline-oakridge-park","group":"gboards","task":"text-to-timeline","title":"Text → collage timeline (Oakridge Park redevelopment)","what":"A heavily specified 16:9 collage-style site-analysis timeline of Oakridge Park, Vancouver — five redevelopment stages, black/white/grey with dark-red hand-drawn overlays and bold serif title.","input":"","prompt":"Generate a horizontal collage-style timeline analysis diagram of the redevelopment of Oakridge Park, Vancouver. Diagram Structure: Place a horizontal timeline across the center of the image with 5 key redevelopment stages: Existing Mall Condition (1959), Redevelopment Vision & Approval (2014), Demolition & Site Preparation (2020), Tower & Podium Construction (2022–2025), Completed Oakridge Park Community (Future Vision). Each stage should include representative imagery, architectural renderings, aerial views, or construction photographs paired with concise descriptions. Create a continuous left-to-right narrative showing the site's transformation over time. Visual Elements: Include aerial photos, site plans, massing diagrams, construction imagery, and final renderings from each phase. Add people, vehicles, and public activities representative of each period. Blend historic mall imagery with contemporary urban development visuals to show the evolution of the site. Visual Style: Use a collage-based architectural presentation style. Base palette should be black, white, and gray with dark red accent graphics. Overlay dark red hand-drawn outlines around major buildings, massing forms, and key interventions. Incorporate low-opacity dark red silhouettes to highlight new towers, parks, and public spaces. Text Elements: Title: \"OAKRIDGE PARK SITE ANALYSIS\" in large bold serif typography using dark red. Include short captions and milestone descriptions for each timeline stage. Use arrows, dates, and graphic callouts to emphasize key moments in the redevelopment process. Atmosphere: Create a unified visual story connecting the original suburban shopping mall to the final mixed-use urban district. Blend historical photographs, construction scenes, architectural drawings, and future renderings into a seamless composition. Emphasize increasing density, public realm improvements, transit integration, and the rooftop park as defining transformations. Technical Requirements: Layout: 16:9 landscape format. Composition: Asymmetrical balance with strong visual hierarchy. Elements: Mix of aerial imagery, architectural renderings, massing diagrams, construction photography, and human activity scenes. Fonts: Bold serif typography with editorial-style annotations. Texture: Vintage collage textures combined with contemporary architectural graphics. Color Palette: Black, white, gray, and dark red accents only. Narrative Quality: Clearly communicate the historical and physical evolution of Oakridge Park from shopping mall to complete urban community.","parts":[{"k":"task","t":"Generate a horizontal collage-style timeline analysis diagram of the Oakridge Park redevelopment"},{"k":"subject","t":"five dated stages from the 1959 mall to the future completed community, in a continuous left-to-right narrative"},{"k":"style","t":"collage-based; black/white/gray with dark red accents, hand-drawn red outlines, low-opacity red silhouettes, vintage collage textures"},{"k":"output","t":"16:9 landscape, bold serif title \"OAKRIDGE PARK SITE ANALYSIS\", captions, arrows, dates, callouts"}],"followups":[],"notes":["The most heavily specified prompt in the library — structure, style, text, atmosphere and technical requirements each get a labelled block."],"srcPage":"Timeline Site Analysis","tier":"public","img":{"after":"content/examples/timeline-oakridge-park/after.jpg"},"modes":["board-layout","diagram","notation-scores"]},{"id":"timeline-sydney-opera-house","group":"gboards","task":"text-to-timeline","title":"Text → massing-evolution timeline (Sydney Opera House)","what":"Generates a vertical timeline board of five named evolution stages of the Sydney Opera House, drawn as consistent axonometric massing diagrams with geometric studies and a single accent colour.","input":"","prompt":"Create a vertical architectural timeline board illustrating the massing evolution of the Sydney Opera House from concept to final construction. Timeline Structure: Present 5 key stages of the project's evolution in chronological order. Use consistent axonometric massing diagrams and concise annotations. Connect each stage with a clear visual timeline. Key Evolution Stages: Original Competition Proposal (1957) – Early sculptural concept with free-form shell roofs emerging from a large podium. Podium Development – Construction and refinement of the stepped podium establishing the building's base and public terraces. Shell Geometry Exploration – Studies testing different shell shapes and structural systems before a buildable solution was found. Spherical Shell Solution – Development of the final geometry where all roof shells are derived from sections of a single sphere, enabling efficient construction. Completed Opera House (1973) – Fully realized building with tiled shells, glazed end walls, and integrated waterfront public spaces. Supporting Graphics: Include geometric studies, shell construction diagrams, and exploded assembly views. Highlight major structural and design breakthroughs with a single accent color. Add brief annotations describing the significance of each stage. Presentation Style: Modern, minimalist architectural graphic design. White background, clean linework, generous spacing, and professional typography. Competition-quality layout emphasizing the evolution of form, geometry, and construction.","parts":[{"k":"task","t":"Create a vertical timeline board illustrating the massing evolution of the Sydney Opera House"},{"k":"subject","t":"five named stages, 1957 competition proposal through 1973 completion, each described in one line"},{"k":"style","t":"consistent axonometric massing diagrams, geometric studies, one accent colour for breakthroughs"},{"k":"output","t":"white background, clean linework, professional typography, competition-quality layout"}],"followups":[],"notes":["Precedent-analysis use of generation: the content of each stage is supplied as researched fact, the AI only draws it."],"srcPage":"Timeline Site Analysis","tier":"public","img":{"after":"content/examples/timeline-sydney-opera-house/after.jpg"},"modes":["board-layout","projection-systems","diagram"]},{"id":"townhouse-plan-to-axon","group":"g2d3d","task":"plan-to-axon","title":"Townhouse landscape plan → 3D axonometric diagram","what":"Lifts a townhouse-complex landscape plan into a clean 3D axonometric site diagram on a plinth, keeping the layout of buildings, roads, courtyards and planting while stripping surrounding context.","input":"A landscape plan of a townhouse complex","prompt":"Transform the attached townhouse complex landscape plan into a clean 3D axonometric architectural diagram. Preserve the layout of the townhouse buildings, roads, pathways, courtyards, planting areas, and open spaces while removing all unnecessary surrounding context. Place the development on a simple square plinth to ground the composition. Use thin linework, subtle material textures, soft ambient shadows, and simplified vegetation to emphasize depth and spatial relationships. The overall style should be minimal, architectural, and diagrammatic, with a white background and presentation-quality graphics suitable for portfolios, design boards, and urban design studies.","parts":[{"k":"task","t":"Transform the attached townhouse complex landscape plan into a clean 3D axonometric architectural diagram"},{"k":"preserve","t":"preserve the layout of the townhouse buildings, roads, pathways, courtyards, planting areas, and open spaces"},{"k":"change","t":"remove all unnecessary surrounding context; place the development on a simple square plinth"},{"k":"style","t":"thin linework, subtle material textures, soft ambient shadows, simplified vegetation; minimal, architectural, diagrammatic, white background"}],"followups":[],"notes":["Same townhouse project as the bird's-eye rendering entry — the RA runs one plan through several output types."],"srcPage":"Photo/Plan to Isometric Diagram","tier":"public","img":{"before":"content/examples/townhouse-plan-to-axon/before.jpg","after":"content/examples/townhouse-plan-to-axon/after.jpg"},"modes":["projection-systems","diagram"]},{"id":"view-exterior-to-aerial","group":"grender","task":"change-view","title":"Bath house exterior → bird's-eye view","what":"Moves the camera to an aerial position over the same bath house, exposing roof geometry, circulation and pool spaces while keeping the project fully consistent with the source render.","input":"An exterior render of the bath house project","prompt":"Create a new photorealistic bird's-eye view render of the bath house project based on the input render. The camera should be positioned from an elevated aerial perspective looking down at the building and surrounding landscape, clearly showcasing the overall architectural form, roof geometry, circulation paths, pool spaces, and relationship to the site. Preserve the exact architectural language, proportions, materials, and design details established in the original render so the project remains fully consistent. Emphasize the warm wood materiality, soft atmospheric lighting, and tranquil spa-like character of the bath house. Outdoor pools should appear warm and inviting, with subtle steam rising from the water to enhance the serene atmosphere. Surrounding landscape elements should feel refined and natural, complementing the architecture without overpowering it. The render should maintain a calm cinematic mood with realistic shadows, reflections, lighting, and environmental depth. Do not redesign the architecture or alter the composition of the project — only generate a believable aerial rendered viewpoint of the same bath house design.","parts":[{"k":"task","t":"Create a new photorealistic bird's-eye view render of the bath house project based on the input render"},{"k":"camera","t":"elevated aerial perspective looking down, showcasing form, roof geometry, circulation paths, pool spaces and site relationship"},{"k":"preserve","t":"exact architectural language, proportions, materials and design details"},{"k":"style","t":"warm wood materiality, steam rising from pools, calm cinematic mood with realistic shadows and reflections"},{"k":"negative","t":"do not redesign the architecture or alter the composition"}],"followups":[],"notes":[],"srcPage":"Changing Rendered Views (1)","tier":"public","img":{"before":"content/examples/view-exterior-to-aerial/before.jpg","after":"content/examples/view-exterior-to-aerial/after.jpg"},"modes":["perspective-view"]},{"id":"view-exterior-to-interior","group":"grender","task":"change-view","title":"Bath house exterior → consistent interior view","what":"Generates an interior perspective of the bath house project from its exterior render, holding the established architectural language, materials and mood so the interior reads as the same building.","input":"An exterior render of the bath house project","prompt":"Create a new rendered image from an interior perspective of the bath house shown in the input render. The new viewpoint should place the camera inside the building, focusing on the warm atmospheric quality of the space and emphasizing the relationship between lighting, wood materiality, and interior architecture. Showcase the wood-lined walls, ceilings, and structural elements with rich texture and soft natural tones. Lighting should feel calm and immersive, combining warm indirect artificial lighting with subtle natural light filtering into the space to create a serene spa-like atmosphere. Maintain the same architectural language, proportions, materials, and design details established in the original render so the interior feels fully consistent with the existing project. Include realistic depth, reflections, shadows, and a refined photorealistic quality while preserving the tranquil mood of the bath house. Do not redesign the architecture or alter the established material palette — only generate a believable interior rendered viewpoint of the same project.","parts":[{"k":"task","t":"Create a new rendered image from an interior perspective of the bath house shown in the input render"},{"k":"camera","t":"camera inside the building, focused on the warm atmospheric quality of the space"},{"k":"preserve","t":"same architectural language, proportions, materials and design details as the original render"},{"k":"light","t":"warm indirect artificial light with subtle natural light — a serene spa-like atmosphere"},{"k":"negative","t":"do not redesign the architecture or alter the established material palette"}],"followups":[],"notes":[],"srcPage":"Changing Rendered Views (1)","tier":"public","img":{"before":"content/examples/view-exterior-to-interior/before.jpg","after":"content/examples/view-exterior-to-interior/after.jpg"},"modes":["perspective-view"]},{"id":"view-markup-arrow","group":"grender","task":"change-view","title":"Arrow markup → render from the marked viewpoint","what":"Draws an arrow on the input image to specify both camera position and viewing direction, then generates a new eye-level render from exactly that spot.","input":"A render of the project with an arrow drawn to mark camera position, height and direction","prompt":"Generate a new rendered image from the exact viewpoint indicated by the drawn arrow on the input image. The camera height should match the height of the arrow itself, creating a true eye-level perspective from that position. The direction the arrow is pointing represents the viewing direction and should determine the orientation of the render. Maintain the exact architectural design, proportions, materials, lighting style, and surrounding context from the original image so the new render feels fully consistent with the existing project. Do not redesign, reposition, or alter the architecture or landscape — only change the camera viewpoint according to the arrow markup. The resulting image should feel spatially accurate and believable to the marked perspective.","parts":[{"k":"task","t":"Generate a new rendered image from the exact viewpoint indicated by the drawn arrow"},{"k":"camera","t":"camera height matches the arrow height (true eye level); arrow direction sets the viewing direction"},{"k":"preserve","t":"exact architectural design, proportions, materials, lighting style and surrounding context"},{"k":"negative","t":"do not redesign, reposition, or alter the architecture or landscape — only the camera changes"}],"followups":[],"notes":[],"srcPage":"Changing Rendered Views (1)","tier":"public","img":{"before":"content/examples/view-markup-arrow/before.jpg","after":"content/examples/view-markup-arrow/after.jpg"},"modes":["perspective-view"]},{"id":"villa-render-to-elevation-svg","group":"g3d2d","task":"image-to-elevation","title":"Villa render → CAD-style elevation (+ SVG step)","what":"The same elevation-extraction prompt applied to a villa render, again followed by the SVG conversion step for downstream CAD editing.","input":"A photorealistic render of a villa in a landscape setting","prompt":"Create a clean, professional architectural elevation drawing of the building. Render the elevation in precise black-and-white linework on a pure white background, showing accurate proportions, façade composition, window and door locations, material joints, and architectural detailing. Use a technical drafting style similar to a CAD-generated elevation, with consistent line weights and crisp edges. Do not use perspective, shadows, or three-dimensional effects—the drawing should remain a flat orthographic elevation suitable for architectural presentation boards. Remove all surrounding context, text, dimensions, and annotations, focusing solely on the building elevation.","parts":[{"k":"task","t":"Create a clean, professional architectural elevation drawing of the building"},{"k":"style","t":"black-and-white CAD-style linework, consistent line weights, pure white background"},{"k":"preserve","t":"accurate proportions, façade composition, openings, material joints, detailing"},{"k":"negative","t":"no perspective, shadows or 3D effects; strip context, text, dimensions, annotations"}],"followups":["Turn this plan to single SVG version of the CAD drawing, keeping the vectorized, clean line style."],"notes":[],"srcPage":"Photo to Elevation (or CAD)","tier":"public","img":{"before":"content/examples/villa-render-to-elevation-svg/before.jpg","after":"content/examples/villa-render-to-elevation-svg/after.jpg","steps":["content/examples/villa-render-to-elevation-svg/step1.jpg"]},"modes":["measured-drawing","perspective-view"]},{"id":"watercolour-plan-to-campus","group":"g2d3d","task":"plan-to-perspective","title":"Watercolour plan → top-down render (school campus)","what":"Replaces the watercolour textures of a landscape plan with realistic materials in a straight overhead render of a secondary school campus, then lowers the camera toward eye level in follow-ups.","input":"A watercolour landscape plan of a school campus site","prompt":"Transform the attached watercolor landscape plan into a photorealistic top-down architectural rendering. Maintain the exact viewpoint, scale, layout, and composition of the original plan with a straight overhead view. Replace watercolor textures with realistic grass, planting, trees, paving, asphalt, and site materials. Model the buildings as a contemporary secondary school campus with modern architecture, outdoor gathering spaces, sports areas, and pedestrian circulation. Add realistic urban context including roads, sidewalks, street trees, and surrounding residential buildings. Use high-quality photorealistic materials, natural daylight, and soft shadows while preserving the original plan geometry exactly.","parts":[{"k":"task","t":"Transform the attached watercolor landscape plan into a photorealistic top-down architectural rendering"},{"k":"camera","t":"maintain the exact viewpoint, scale, layout, and composition with a straight overhead view"},{"k":"change","t":"replace watercolor textures with realistic grass, planting, trees, paving, asphalt, and site materials; model the buildings as a contemporary secondary school campus; add roads, sidewalks, street trees, and surrounding residential buildings"},{"k":"preserve","t":"preserve the original plan geometry exactly"},{"k":"light","t":"high-quality photorealistic materials, natural daylight, and soft shadows"}],"followups":["Lower the camera angle to bring it closer to eye level, allowing more of the surrounding city to be visible in the background.","Create a eye level perspective view from the courtyard, looking toward the building, with the landscape design area in the foreground."],"notes":[],"srcPage":"Plan to Bird's-Eye & Perspective","tier":"public","img":{"before":"content/examples/watercolour-plan-to-campus/before.jpg","after":"content/examples/watercolour-plan-to-campus/after.jpg","steps":["content/examples/watercolour-plan-to-campus/step1.jpg","content/examples/watercolour-plan-to-campus/step2.jpg"]},"modes":["sketch"]}],"methods":[{"id":"concept-generation","title":"Concept Generation","stage":"ideation","what":"Large language models (LLMs) can support early concept development by translating simple inputs — such as objects, feelings, or precedents — into structured descriptions of spatial, atmospheric, and material qualities, helping clarify and expand initial design ideas.","keyIdeas":["LLMs are highly effective at interpreting casual, informal descriptions — ideas do not need rigid or technical language; even simple prompts get expanded into concepts, relationships and design possibilities. Recommended: ChatGPT.","Brainstorm pattern 1 — object to conceptual/physical qualities: e.g. \"Translate the conceptual, cultural and physical qualities of a Chinese lucky knot into potential architectural design ideas in point form\" (yields interconnectedness, looping geometry, layering/weaving, structural expression, thresholds, light-and-shadow patterns...).","Brainstorm pattern 2 — existing site conditions: e.g. \"In point form, analyze the social, environmental and historical conditions of Vancouver's John Hendry Park that could be potential design drivers\" (cultural diversity, Trout Lake ecology, stormwater, Indigenous land relationships, climate resilience...).","Brainstorm pattern 3 — programmatic & spatial iteration: ask what programmatic and spatial considerations matter for the building type and how to iterate them.","Brainstorm pattern 4 — summarize and connect key design drivers of precedents (e.g. Wormhole Library × Serpentine North Gallery) and how one relates to another.","LLM → image generation: after identifying key drivers, ask the LLM to write the image prompt for you, so abstract concepts become visualizable iterations for comparison."],"template":"Ask: Based on the qualities of a [source: object/site/precedent]: (insert previous points), create a prompt for Gemini to create [N] visual iterations of how these qualities could translate into a [project type] design.","steps":[{"text":"Feed the LLM-refined prompt into Gemini (the RA's recommended image generator) — here: six concept iterations of a community centre derived from the qualities of a Chinese lucky knot, each with an exterior and interior perspective.","img":"content/methods/concept-generation/img1.jpg"}],"tier":"public"},{"id":"constraint-locking","title":"Constraint Locking","stage":"iteration","what":"As visual generation workflows rely on a meticulous back-and-forth, image distortion commonly emerges as ideas get refined — AI alters components that were never meant to change and builds on those errors. Constraint locking preserves successful aspects of an output by stating clear visual and spatial constraints in every subsequent prompt.","keyIdeas":["State and/or markup areas to preserve.","Reuse (input) previous references, renders and outputs.","Use precise and strict language.","Once satisfied with an element, explicitly prompt the AI to preserve that exact feature while modifying the next aspect — change one component at a time.","At advanced refinement stages unintended changes are hard to reverse, because AI systems retain and build upon characteristics of previous outputs — lock early.","See the Iterative Prompting page for a full workflow with constraint locking in each consecutive prompt."],"template":"[Geometry]: do not alter any other elements, only change the form of the ———  ·  [Material]: change —— and preserve [Geometry] including ———  ·  [Furnishing/Details]: preserve the [Geometry], [Material] and ——— only add ———  ·  [Atmosphere]: preserve the exact [Geometry], [Material], and [Furnishing/Details] and only change the atmosphere from —— to ——","steps":[],"tier":"public"},{"id":"hybrid-workflow","title":"Hybrid Workflow","stage":"iteration","what":"Strong workflows move fluidly between platforms and methods — GPT, manual modelling, hand sketching, markup, rendering tools, and generative systems like Meshy AI. The more references, iterations and forms of input AI receives, the more accurate, controlled and consistent the outputs become; combining analogue and digital approaches also helps maintain human authorship.","keyIdeas":["Input manual visual references for the idea to understand (e.g. mood boards, CAD models, sketch models).","Do not rely solely on prompting.","Manipulate AI outputs using other platforms/methods (e.g. sketch overlay, refine form in CAD, collage materials)."],"template":"","steps":[],"tier":"public"},{"id":"identifying-gaps","title":"Identifying Gaps","stage":"final","what":"AI image generation can produce visually convincing results while still containing significant inaccuracies — inconsistent views, erroneous technical drawings, distorted proportions or perspectives. Outputs must be critically reviewed for consistency, accuracy and realistic spatial representation; when prompting alone cannot fix the issues, manual intervention through modeling, drafting or post-production becomes necessary.","keyIdeas":["Unrealistic perspectives & spatial relationships.","Inaccurate relative human proportions (e.g. a person entering the cafe through a window).","Material or lighting inconsistencies across images (e.g. an inconsistent mesh facade; a lantern light rendered as transparent).","Illogical structural or architectural elements (e.g. an impossible roof structure; openings facing a highway).","Incorrect technical drawings or geometry (e.g. a plan drawn inside a section; inconsistent roof forms between drawings).","Inconsistencies between rendered views (wrong spatial layout, different ceiling, voids in the facade).","Refer to the 04 Problem Solving methods for workarounds."],"template":"","steps":[{"text":"Inaccurate human proportions: a person entering the cafe through a window.","img":"content/methods/identifying-gaps/img1.jpg"},{"text":"Material/lighting inconsistency: the perforated mesh facade changes pattern between views of the same building.","img":"content/methods/identifying-gaps/img2.jpg"},{"text":"Incorrect technical drawing: a plan appears inside what is labelled a section.","img":"content/methods/identifying-gaps/img3.jpg"}],"tier":"public"},{"id":"iterative-model-generations","title":"Iterative Model (Diagrammatic) Generations","stage":"ideation","what":"Generates multiple completely different early-stage parti concepts as clean black-and-white isometric linework diagrams — deliberately not renders — so a project can be explored as competing organizational ideas before any one is developed.","keyIdeas":["Open with the role: \"Act as a conceptual architectural design AI generating early-stage architectural ideation diagrams\".","Ask for several completely different architectural concepts, not variations of one form (\"some schemes minimal and linear, others carved into the site, others modular and dispersed\").","Describe the site and program richly (cliffside terrain, rail-yard infrastructure) so the parti ideas respond to real conditions — circulation, sectional relationships, landscape integration.","Lock the output style: clean black-and-white isometric linework only, thin lineweights, minimal shading, competition parti-diagram aesthetics; explicitly no realistic textures, materials or rendering effects."],"template":"Act as a conceptual architectural design AI generating early-stage architectural ideation diagrams. Create multiple distinct design iterations for a [program] located [site]. Generate several completely different architectural concepts rather than variations of one form. The output should be clean black-and-white isometric architectural linework diagrams only — not photorealistic renders.","steps":[{"text":"Example 1 — Coastal research library and public observatory at Lighthouse Park: embedded architecture, cantilevers, terraced forms, lookout spaces and fragmented masses explored across distinct parti diagrams.","img":"content/methods/iterative-model-generations/img1.jpg"},{"text":"Example 2 — Urban food market and vertical community farm in a rail-yard district near Thornton Park: stacked, low-rise and modular-infrastructural concepts exploring terraced farming, greenhouse volumes and elevated circulation.","img":"content/methods/iterative-model-generations/img2.jpg"}],"tier":"public"},{"id":"iterative-prompting","title":"Iterative Prompting","stage":"iteration","what":"Manual writing alone is often insufficient for effective AI prompt generation because it may convey specificity incompletely — AI \"fills in gaps\" when information is ambiguous, producing unintended elements. Gap-filling can be valuable during exploration, but when refining a developed concept it becomes counterproductive, so iteration proceeds in small, precise, one-change-at-a-time prompts.","keyIdeas":["1–2 tasks per prompt.","Provide references.","State constraints: what NOT to change vs. what to change.","State specific and explicit changes.","Separate geometric iteration from material iteration."],"template":"Recommended stages of iteration: [Geometry] → [Material] → [Furnishing/Details] → [Atmosphere] → [Rendered Views]","steps":[{"text":"Base image: an AI-generated library render is chosen as the working basis.","img":"content/methods/iterative-prompting/img1.jpg"},{"text":"Prompt 1 [Geometry] — with a hand sketch attached: \"Modify only the roof form of the library to follow the curved sloping profile shown in the attached sketch... Do not alter any other elements.\""},{"text":"Prompt 2 [Material] — \"Change the primary structural and metal facade components into a rich red brick material while preserving the existing architectural form and detailing... Preserve everything else exactly.\""},{"text":"Prompt 3 [Material 2] — \"Change the wood slats into a dark walnut.\""},{"text":"Prompt 4 [Details/Facade] — with markup of the previous output plus a Perkins&Will precedent image: \"Add a secondary facade layer onto the circled portions using a black perforated metal cladding system... Preserve the exact building form, materials outside the specified areas, lighting, atmosphere, context and camera composition.\"","img":"content/methods/iterative-prompting/img5.jpg"},{"text":"Prompt 5 [Atmosphere] — \"Change the render to a night-time scene while preserving the exact building form, materials, context, and camera composition... warm interior glow filtering through the perforated cladding.\""},{"text":"Prompt 6 [Alternate Rendered Views] — \"Generate four additional rendered views of the same library project that remain fully consistent with the original input image... Do not redesign or reinterpret the architecture.\""},{"text":"Prompt 7 [Refinement] — with markup: \"Close the perforation in the circled area... Do not change anything else in the image.\"","img":"content/methods/iterative-prompting/img8.jpg"}],"tier":"public"},{"id":"manual-intervention","title":"Manual Intervention","stage":"problem","what":"Knowing when to move from AI generation into manual modeling preserves design accuracy, consistency and technical control. Repeated inaccuracies or unresponsiveness to prompts signal that manual work will resolve the design — and often saves time over ongoing unsuccessful prompting.","keyIdeas":["Key observation: outputs generated from manual models or drawings follow the original geometry much more closely, giving greater control over proportions, form and consistency.","Re-model in CAD — when prompting for a larger roof overhang repeatedly failed (the pattern changed, the overhang stayed), modelling in Rhino set the overhang at exactly 3 m, added interior/exterior components, and the model was fed back into Gemini.","Re-sketch the form — a hand sketch of an alternate roof gave the AI the exact wanted shape and height in one step, avoiding long chains of corrective prompts.","Use editing software (Photoshop, Lightroom) for small, localized, purely visual fixes: lighting/exposure, colour correction, object cleanup, contrast, shadows/reflections, adding entourage manually, fixing textures, compositing multiple successful outputs, retouching, and keeping boards consistent."],"template":"","steps":[{"text":"Ongoing issue: form and roof distorted over iterations; numerous prompts for a larger roof overhang failed — the pattern changed while the overhang stayed stagnant.","img":"content/methods/manual-intervention/img1.jpg"},{"text":"Manually modeling in Rhino: exact 3 m overhang, detailed interior and exterior components, full layout with washroom, kitchen and service counter.","img":"content/methods/manual-intervention/img2.jpg"},{"text":"Feed back into Gemini: the render generated from the manual model follows the intended geometry closely.","img":"content/methods/manual-intervention/img3.jpg"}],"tier":"public"},{"id":"markup","title":"Markup","stage":"iteration","what":"Markup used together with prompting gives AI direct visual guidance on where changes should occur, improving control and consistency during iteration. It can preserve areas, guide design changes, indicate material adjustments, and reduce unwanted modifications throughout the generation process.","keyIdeas":["Merging iterations — circle the elements to take from one iteration and where they go in another (\"only modify the elements circled in yellow on the 4th tower iteration by replacing them with the elements circled in red from the 1st\").","Constraint locking — circle what must NOT change (\"do not alter or modify the tree circled in pink in any way\") while transforming everything around it.","Highlight additions/removals — circle the zones where a new element (e.g. a brise soleil facade) may be added; nothing outside the circles may change.","Direct render viewpoint — draw an arrow to set camera position, height and viewing direction for a new render."],"template":"","steps":[{"text":"Merging iterations: markup input with yellow and red circles across a diagram sheet of tower iterations.","img":"content/methods/markup/img1.jpg"},{"text":"Output: the circled elements of iteration 1 are transplanted onto iteration 4, with all other linework, geometry and diagram style untouched.","img":"content/methods/markup/img2.jpg"},{"text":"Highlight additions: circled zones on a mall render receive a brise soleil system matched to the building's structural and material language; everything outside the circles is preserved.","img":"content/methods/markup/img3.jpg"}],"tier":"public"},{"id":"new-chats-edit-regenerate","title":"New Chats, Prompt Edit & Regenerate","stage":"problem","what":"Three escalating chat-level tactics for when generation goes wrong: start a new chat with the last successful image as reference, use the regenerate button for variations with continuity, and edit the prompt in place to break the AI's attachment to failed generations.","keyIdeas":["01 New chat — when AI makes repeated mistakes or produces near-identical outputs, start fresh using the last successful image as the new reference point; also do this when switching projects, since generation carries over ideas, forms and styles from the previous design.","02 Regenerate button — a new chat may repeat old mistakes because corrections are not retained; regenerating within the same workflow gives alternative variations with better contextual continuity. Often takes 2–3 regenerations to get a refined result.","03 Prompt edit — if new chats and regeneration keep failing, the prompt likely lacks detail. Editing replaces the previous prompt rather than keeping it in history, so the AI is less influenced by earlier unsuccessful outputs; editing also auto-generates a new image."],"template":"","steps":[{"text":"Starting a new chat with the last successful output attached as the reference image.","img":"content/methods/new-chats-edit-regenerate/img1.jpg"},{"text":"The regenerate function produces alternative variations while retaining workflow context.","img":"content/methods/new-chats-edit-regenerate/img2.jpg"},{"text":"Prompt edit replaces the failed prompt in place, removing it from the chat history the AI conditions on.","img":"content/methods/new-chats-edit-regenerate/img3.jpg"}],"tier":"public"},{"id":"post-processing","title":"Post Processing","stage":"final","what":"AI-generated outputs are often limited in resolution, and image quality degrades across longer iterative workflows. Post-processing is essential to upscale, refine and restore clarity using external tools, ensuring final visuals meet architectural presentation standards without altering the underlying design intent.","keyIdeas":["Upscale before presenting — quality loss accumulates across iterations.","Upscaling resources named by the RA: ILoveIMG, Upscale Media, Upscayl.","Post-processing restores clarity; it must not alter the underlying design intent."],"template":"","steps":[],"tier":"public"},{"id":"precedent-exploration","title":"Precedent Exploration","stage":"ideation","what":"Uses named precedents as the vocabulary of a generation prompt — merging the massing of one project with the facade system of another to produce new conceptual hybrids, iterated several times from the same prompt.","keyIdeas":["Name the precedents and say exactly what to take from each (massing from Dongdaemun Design Plaza and Heydar Aliyev Center; facade from Kukje Gallery's layered metal mesh).","Open with a role: \"Act as a world-class architectural visualization and conceptual design AI\".","Describe the intended qualities, not just the source buildings — fluid sculptural geometry, lantern-like translucency, monumental modular rhythm.","Run the same prompt several times: each generation is one iteration; compare them rather than accepting the first.","Precedents can also be crossed against a material idea — e.g. brutalist stacking (Habitat 67, UC Innovation Center) reinterpreted in Maison Hermès glass brick for a night-time lantern effect."],"template":"Act as a world-class architectural visualization AI. Create a highly detailed render of a [type] inspired by the [quality] of [precedent A] and the [quality] of [precedent B]. The facade system should be inspired by [precedent C]. [setting, lighting, render style...]","steps":[{"text":"Example 1 — Merging freeform icons: Heydar Aliyev Center + Dongdaemun Design Plaza massing wrapped in a Kukje Gallery-style perforated metal mesh veil; three iterations generated.","img":"content/methods/precedent-exploration/img1.jpg"},{"text":"Example 2 — Altering brutalism: Habitat 67 / UC Innovation Center stacked modular massing re-skinned in translucent Maison Hermès glass brick, rendered at night as glowing office modules; three iterations.","img":"content/methods/precedent-exploration/img2.jpg"}],"tier":"public"},{"id":"prompt-engineering","title":"Prompt Engineering","stage":"ideation","what":"After narrowing down core design ideas, prompt engineering becomes a process of defining clear criteria, priorities, and constraints for the LLM to refine into prompts for AI visual generators — establishing what should remain fixed, what can vary, and the overall spatial or atmospheric intent.","keyIdeas":["Use an LLM (ChatGPT recommended) for prompting: feed your criteria and constraints in and let it write the generator prompt.","1 · Define role & objective — AI performs better when it knows the task: discipline, output image type, priority. ✘ \"Make this render better\" ✔ \"Act as an architectural visualization assistant. Generate a photorealistic exterior render while preserving the exact geometry and camera position from the reference Rhino model.\"","2 · Establish constraints — image systems hallucinate unless you specify what MUST stay fixed, what MAY change, and what MUST NOT change.","3 · Use a hierarchy of importance — prompts contain conflicting goals; without priorities the AI may sacrifice geometry for aesthetics (\"Priority order: 1. Match Rhino geometry exactly...\").","4 · Describe spatial logic, not just appearance — explain why elements exist (\"louvers transition from closed to open in response to solar exposure and privacy\").","5 · Anchor the AI with reference inputs — Rhino screenshots, massing diagrams, depth maps, material references, precedent imagery; generally include one geometry, one material, one atmosphere and one lighting reference.","6 · Specify camera and composition — eye level, focal length, perspective type, framing, vanishing direction (\"eye-level at ~1.6 m with a 28 mm architectural lens...\").","7 · Control style through material language — avoid \"beautiful / modern / futuristic\"; describe materiality, lighting behaviour, atmosphere, texture (\"cast-in-place concrete with board-form texture, overcast Pacific Northwest lighting...\").","8 · Use sequential workflow prompts — iterate one element at a time with high specificity; asking for many changes at once reduces control."],"template":"Preserve: [building massing / facade proportions / louver orientation / camera angle]. Only modify: [material realism / lighting / entourage]. Do not: [alter floor count / add new windows / change structural rhythm].","steps":[],"tier":"public"},{"id":"reference-inputs","title":"Reference Inputs","stage":"ideation","what":"Anchors generation with visual and numerical references — mood boards, spreadsheets, physical sketch models — so the AI reinterprets your actual material rather than inventing from words alone.","keyIdeas":["Mood boards transfer a whole design language: a Japanese-interior mood board renovates a living-room render while the room's geometry, camera and openings stay locked.","Spreadsheets are valid inputs: an Excel table of tree species and quantities plus a site aerial drives black-and-white master-plan diagrams of planting strategies.","Physical sketch models can be reinterpreted: a dowel model becomes a structural framework for a pavilion while keeping the model's proportions and spatial intent.","State explicitly how each reference may be used (design language yes, background composition no)."],"template":"","steps":[{"text":"Example 1 — Mood board: renovate the provided living room using the attached Japanese architecture/interior mood board as the primary design reference; preserve layout, proportions, ceiling height, camera and openings exactly; redesign materiality, furniture, lighting and decor toward a calm, tactile, contemporary-Japanese language.","img":"content/methods/reference-inputs/img1.jpg"},{"text":"Example 2 — Spreadsheet to diagram: use an Excel table of species and quantities (Douglas Fir, Western Redcedar, Western Hemlock, Sitka Spruce) with an aerial of the site to generate tree-placement master plan iterations for heat-island mitigation around the UBC Alumni Centre.","img":"content/methods/reference-inputs/img2.jpg"},{"text":"Example 3 — Model to design idea: transform a physical dowel sketch model into a contemporary pavilion, interpreting the dowels as the structural framework and preserving the handcrafted proportions and spatial intent rather than redesigning.","img":"content/methods/reference-inputs/img3.jpg"}],"tier":"public"},{"id":"regenerate-alternate-view","title":"Regenerate From Alternate View","stage":"problem","what":"Regenerating from a different view is an effective problem-solving method when AI struggles with a form, material or spatial relationship: another angle can make the intended geometry clearer, reduce distortions, reveal hidden components, and provide stronger visual references for later iterations.","keyIdeas":["In the bath house project, all renders taken from the left side of the building kept coming out inconsistent with the original render (wrong entrance, wrong main space).","Regenerating from other views — an accurate bird's-eye render and an accurate pool-to-main-space render — rebuilt the AI's spatial understanding.","RA note: input as many accurate renders as possible when generating new ones; more correct views give the AI a stronger spatial understanding and greater consistency across all renders.","Even so, expect some views to fail (incorrect entrance and interior renders appear alongside accurate top-floor and interior ones) — keep the accurate ones and feed them forward."],"template":"","steps":[{"text":"Original AI-generated render of the bath house — the fixed reference for all view changes.","img":"content/methods/regenerate-alternate-view/img1.jpg"},{"text":"Failure mode: renders from the building's left side are inconsistent with the original (incorrect entrance render shown).","img":"content/methods/regenerate-alternate-view/img2.jpg"},{"text":"After regenerating from accurate alternate views and feeding them back in, consistent renders emerge (accurate interior render shown).","img":"content/methods/regenerate-alternate-view/img3.jpg"}],"tier":"public"},{"id":"rendering","title":"Rendering","stage":"final","what":"A general workflow for final renders: open with 1–2 short sentences establishing the overarching goal and what to emphasize most (e.g. light diffusion from the facade to create a serene interior atmosphere), then specify the scene in a strict bullet structure.","keyIdeas":["Start with 1–2 sentences stating the render's overarching goal and main emphasis.","Optionally add: markup on the reference image (arrow for viewpoint) and mood boards for material and atmosphere.","Feed CAD/Rhino screenshots as geometry references and require the geometry to be maintained.","Key components for iterating a render afterwards: Adding Context · Controlling Materiality · Changing Render Styles · Changing Rendered Views."],"template":"[building type + design intent/conceptual goal] · [massing + geometry] · [materials] · [lighting] · [camera composition] · [site context] · [human activity] · [rendering style]","steps":[{"text":"CAD screenshot inputs: two Rhino viewport captures of the waffle-roof cafe model provide the geometry anchor.","img":"content/methods/rendering/img1.jpg"},{"text":"Prompt: \"Based on the reference images, create a photorealistic render to emphasize the relationship between natural light, warmth, and community within the cafe space...\" followed by bullets — waffle roof for diffused light, maintain geometries from the reference, dark walnut + glass, sunny natural lighting, viewpoint at the front-left wall, grass pad overlooking the Vancouver Sea Wall, lively patio, photo-realistic render.","img":"content/methods/rendering/img2.jpg"}],"tier":"public"},{"id":"task-simplification","title":"Task Simplification","stage":"problem","what":"Rather than asking the AI to change multiple elements at once, work in smaller steps where each prompt modifies only one component. This reduces unintended changes, improves consistency, and lets you evaluate each iteration before the next adjustment; an LLM can also shorten or simplify prompts, since overly long instructions confuse the model.","keyIdeas":["One component per prompt; evaluate before moving on.","Recommended workflow: [Geometry] → [Materials] → [Furnishing/Details] → [Atmosphere].","✓ Good: \"Change the roof into a sloped roof\" → \"Preserve the geometry of the roof and only replace the metal parts of the facade with red brick\" → \"Preserve all geometries and materials. Render the library at night time with warm interior lighting\".","✗ Bad: \"Change the roof into a sloped roof, turn the metal facade into red brick, and render the library at night time with warm lighting.\"","Use an LLM to shorten or simplify prompts that have grown too complex."],"template":"Prompt 1: change [one component]. Prompt 2: preserve [component 1] and only change [component 2]. Prompt 3: preserve all previous decisions and only change [component 3].","steps":[],"tier":"public"},{"id":"technical-drawing-3d-2d","title":"Technical Drawing (3D to 2D)","stage":"final","what":"Extracts two-dimensional technical material from three-dimensional inputs: full drawing sets and diagram series from renders, site plans from aerials, exploded assembly drawings from CAD models, and master plans from numerical spreadsheets.","keyIdeas":["Render → 2D: from project renders, generate plans, sections, elevations and facade details as one consistent black-and-white drafting set.","Diagram generation: circulation, exploded isometric by floor, accessibility and view-analysis diagrams from the same design reference.","Numerical data → masterplan: a spreadsheet of tree species/quantities drives plan-diagram iterations.","Aerial → plan: convert aerial photography into clean CAD-style linework site plans.","CAD → exploded assembly diagram: a Rhino screenshot becomes an exploded isometric that stays fully consistent with the modelled geometry.","Always demand consistency across the set — line hierarchy, poché, annotations to professional drafting standards."],"template":"","steps":[{"text":"Render to 2D: library renders become a full technical drawing set with plans, sections, elevations and a perforated-panel detail.","img":"content/methods/technical-drawing-3d-2d/img1.jpg"},{"text":"Diagram generation: circulation, exploded isometric, accessibility and view analysis in a uniform black-and-white technical style.","img":"content/methods/technical-drawing-3d-2d/img2.jpg"},{"text":"CAD to exploded assembly: the Rhino cafe model separated vertically into aligned structural, floor, roof and facade layers.","img":"content/methods/technical-drawing-3d-2d/img3.jpg"}],"tier":"public"},{"id":"workflow-documentation","title":"Workflow Documentation","stage":"final","what":"Documenting AI image generation workflows demonstrates authorship, design intent, and the iterative decision-making behind the final output. Organized records of prompts, outputs, refinements and edits (Notion, Word, Google Docs) show the designer actively guided the work, improve transparency, and allow revision tracking.","keyIdeas":["Checklist: original concept sketches and diagrams.","Initial prompts used for generation, plus prompt revisions and iterative refinements.","Input images, models, or mood boards cited.","AI-generated outputs from each stage of development.","Notes explaining design decisions and reasoning behind changes.","Manual edits completed outside the AI platform, and technical corrections or redraws done manually.","References or precedents that informed the design direction.","Final selected outputs and the rationale for selection.","Any post-production work such as Photoshop, CAD, or rendering edits.","Compile the process into a structured archive or PDF."],"template":"","steps":[],"tier":"public"}]};
